-- FoodBridge: all migrations in order. Generated by `npm run db:bundle` — do not edit.
-- Paste into Supabase Dashboard → SQL Editor → Run (on a fresh project).

-- ===== 20261027000001_schema.sql =====
-- =====================================================================
-- FoodBridge — core schema, constraints, indexes
-- All timestamps are timestamptz (stored in UTC).
-- =====================================================================

create extension if not exists pgcrypto with schema extensions;

-- Internal helpers live in a schema that PostgREST does not expose.
create schema if not exists private;
grant usage on schema private to anon, authenticated, service_role;

-- ---------------------------------------------------------------------
-- Organizations
-- ---------------------------------------------------------------------
create table public.organizations (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(name) between 2 and 120),
  kind text not null check (kind in ('donor', 'receiver')),
  org_type text not null default 'other' check (org_type in (
    'restaurant', 'canteen', 'grocery', 'banquet_hall', 'community_kitchen',
    'ngo', 'food_bank', 'community_org', 'other')),
  address text check (char_length(address) <= 300),
  city text check (char_length(city) <= 80),
  latitude double precision check (latitude between -90 and 90),
  longitude double precision check (longitude between -180 and 180),
  has_refrigeration boolean not null default false,
  has_freezer boolean not null default false,
  capacity_meals integer not null default 0 check (capacity_meals between 0 and 100000),
  verification_status text not null default 'pending'
    check (verification_status in ('pending', 'verified', 'rejected')),
  verification_note text check (char_length(verification_note) <= 500),
  is_demo boolean not null default false,
  created_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index organizations_kind_idx on public.organizations (kind, verification_status);

-- ---------------------------------------------------------------------
-- Profiles (1:1 with auth.users)
-- ---------------------------------------------------------------------
create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  full_name text not null default '' check (char_length(full_name) <= 120),
  email text,
  phone text check (char_length(phone) <= 30),
  role text not null default 'volunteer' check (role in ('donor', 'receiver', 'volunteer', 'admin')),
  organization_id uuid references public.organizations (id) on delete set null,
  is_demo boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index profiles_org_idx on public.profiles (organization_id);
create index profiles_role_idx on public.profiles (role);

create table public.organization_members (
  organization_id uuid not null references public.organizations (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  member_role text not null default 'member' check (member_role in ('owner', 'member')),
  created_at timestamptz not null default now(),
  primary key (organization_id, user_id)
);
create index organization_members_user_idx on public.organization_members (user_id);

-- ---------------------------------------------------------------------
-- Food listings
-- ---------------------------------------------------------------------
create table public.food_listings (
  id uuid primary key default gen_random_uuid(),
  donor_org_id uuid not null references public.organizations (id) on delete cascade,
  created_by uuid references auth.users (id) on delete set null,
  title text not null check (char_length(title) between 3 and 120),
  description text check (char_length(description) <= 1000),
  category text not null check (category in (
    'cooked_meals', 'bakery', 'fruits', 'vegetables', 'packaged_food', 'dairy', 'other')),
  diet text not null check (diet in ('veg', 'non_veg', 'vegan')),
  quantity numeric(10, 2) not null check (quantity > 0 and quantity <= 100000),
  quantity_unit text not null check (quantity_unit in ('kg', 'portions', 'packets', 'trays', 'litres', 'items')),
  estimated_meals integer not null check (estimated_meals between 1 and 100000),
  prepared_at timestamptz,
  safe_until timestamptz not null,
  pickup_start timestamptz not null,
  pickup_end timestamptz not null,
  storage_requirement text not null check (storage_requirement in ('ambient', 'refrigerated', 'frozen')),
  packaging text check (char_length(packaging) <= 200),
  allergens text[] not null default '{}',
  pickup_address text not null check (char_length(pickup_address) between 3 and 300),
  latitude double precision not null check (latitude between -90 and 90),
  longitude double precision not null check (longitude between -180 and 180),
  max_radius_km numeric(6, 2) not null default 15 check (max_radius_km > 0 and max_radius_km <= 100),
  status text not null default 'available' check (status in (
    'available', 'reserved', 'collected', 'completed', 'expired', 'cancelled', 'removed')),
  handling_confirmed boolean not null check (handling_confirmed),
  moderation_note text check (char_length(moderation_note) <= 500),
  expiry_warned_at timestamptz,
  is_demo boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint pickup_window_order check (pickup_start < pickup_end),
  constraint pickup_within_safe_deadline check (pickup_end <= safe_until),
  constraint prepared_before_deadline check (prepared_at is null or prepared_at < safe_until)
);
create index food_listings_status_idx on public.food_listings (status, safe_until);
create index food_listings_donor_idx on public.food_listings (donor_org_id, created_at desc);

-- ---------------------------------------------------------------------
-- Food requests
-- ---------------------------------------------------------------------
create table public.food_requests (
  id uuid primary key default gen_random_uuid(),
  listing_id uuid not null references public.food_listings (id) on delete cascade,
  receiver_org_id uuid not null references public.organizations (id) on delete cascade,
  requested_by uuid references auth.users (id) on delete set null,
  requested_quantity numeric(10, 2) not null check (requested_quantity > 0),
  message text check (char_length(message) <= 500),
  status text not null default 'pending' check (status in ('pending', 'accepted', 'rejected', 'cancelled')),
  distance_km numeric(8, 2),
  decision_note text check (char_length(decision_note) <= 500),
  decided_by uuid references auth.users (id) on delete set null,
  decided_at timestamptz,
  is_demo boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
-- One accepted receiver per listing (MVP: no partial fulfilment).
create unique index food_requests_one_accepted on public.food_requests (listing_id) where status = 'accepted';
-- One open request per organization per listing.
create unique index food_requests_one_open_per_org on public.food_requests (listing_id, receiver_org_id)
  where status in ('pending', 'accepted');
create index food_requests_receiver_idx on public.food_requests (receiver_org_id, created_at desc);

-- ---------------------------------------------------------------------
-- Pickups + handover verification
-- ---------------------------------------------------------------------
create table public.pickups (
  id uuid primary key default gen_random_uuid(),
  listing_id uuid not null references public.food_listings (id) on delete cascade,
  request_id uuid not null unique references public.food_requests (id) on delete cascade,
  donor_org_id uuid not null references public.organizations (id) on delete cascade,
  receiver_org_id uuid not null references public.organizations (id) on delete cascade,
  volunteer_id uuid references public.profiles (id) on delete set null,
  status text not null default 'scheduled' check (status in (
    'scheduled', 'assigned', 'en_route', 'arrived', 'collected', 'verified', 'cancelled', 'expired')),
  assigned_at timestamptz,
  en_route_at timestamptz,
  arrived_at timestamptz,
  collected_at timestamptz,
  collected_by uuid references auth.users (id) on delete set null,
  verified_at timestamptz,
  verified_by uuid references auth.users (id) on delete set null,
  cancelled_at timestamptz,
  is_demo boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create unique index pickups_one_active_per_listing on public.pickups (listing_id)
  where status not in ('cancelled', 'expired');
create index pickups_volunteer_idx on public.pickups (volunteer_id);
create index pickups_receiver_idx on public.pickups (receiver_org_id);
create index pickups_donor_idx on public.pickups (donor_org_id);

-- Only bcrypt hashes of handover codes are stored. No API role can read this table.
create table public.pickup_verifications (
  id uuid primary key default gen_random_uuid(),
  pickup_id uuid not null references public.pickups (id) on delete cascade,
  code_hash text not null,
  expires_at timestamptz not null,
  attempts integer not null default 0 check (attempts >= 0),
  max_attempts integer not null default 5 check (max_attempts > 0),
  used_at timestamptz,
  used_by uuid references auth.users (id) on delete set null,
  invalidated_at timestamptz,
  created_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now()
);
create index pickup_verifications_pickup_idx on public.pickup_verifications (pickup_id, created_at desc);

-- ---------------------------------------------------------------------
-- Notifications
-- ---------------------------------------------------------------------
create table public.notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  type text not null,
  title text not null,
  body text,
  link text,
  read_at timestamptz,
  created_at timestamptz not null default now()
);
create index notifications_user_idx on public.notifications (user_id, created_at desc);

-- ---------------------------------------------------------------------
-- Audit trail (append-only)
-- ---------------------------------------------------------------------
create table public.audit_events (
  id bigint generated always as identity primary key,
  actor_id uuid references auth.users (id) on delete set null,
  action text not null,
  entity_type text not null,
  entity_id uuid,
  listing_id uuid,
  metadata jsonb not null default '{}'::jsonb,
  is_demo boolean not null default false,
  created_at timestamptz not null default now()
);
create index audit_events_listing_idx on public.audit_events (listing_id, created_at desc);
create index audit_events_created_idx on public.audit_events (created_at desc);
create index audit_events_actor_idx on public.audit_events (actor_id);

-- ===== 20261027000002_security.sql =====
-- =====================================================================
-- FoodBridge — helper functions, triggers, privileges and RLS
-- =====================================================================

-- ---------------------------------------------------------------------
-- Private helpers (not exposed through the API)
-- ---------------------------------------------------------------------
create or replace function private.haversine_km(lat1 double precision, lon1 double precision,
                                                lat2 double precision, lon2 double precision)
returns double precision language sql immutable as $$
  select case when lat1 is null or lon1 is null or lat2 is null or lon2 is null then null
  else 2 * 6371.0088 * asin(sqrt(
    power(sin(radians(lat2 - lat1) / 2), 2) +
    cos(radians(lat1)) * cos(radians(lat2)) * power(sin(radians(lon2 - lon1) / 2), 2)))
  end
$$;

create or replace function private.try_float(v text)
returns double precision language plpgsql immutable as $$
begin
  return v::double precision;
exception when others then
  return null;
end $$;

create or replace function private.current_role_name()
returns text language sql stable security definer set search_path = public, pg_temp as $$
  select role from public.profiles where id = auth.uid()
$$;

-- Full (non-demo) administrator.
create or replace function private.is_admin()
returns boolean language sql stable security definer set search_path = public, pg_temp as $$
  select exists (select 1 from public.profiles where id = auth.uid() and role = 'admin' and not is_demo)
$$;

-- Demo administrator: may only see / act on demo records.
create or replace function private.is_demo_admin()
returns boolean language sql stable security definer set search_path = public, pg_temp as $$
  select exists (select 1 from public.profiles where id = auth.uid() and role = 'admin' and is_demo)
$$;

create or replace function private.admin_can_see(p_is_demo boolean)
returns boolean language sql stable security definer set search_path = public, pg_temp as $$
  select private.is_admin() or (private.is_demo_admin() and coalesce(p_is_demo, false))
$$;

create or replace function private.is_org_member(p_org uuid)
returns boolean language sql stable security definer set search_path = public, pg_temp as $$
  select exists (select 1 from public.organization_members where organization_id = p_org and user_id = auth.uid())
$$;

create or replace function private.is_listing_donor(p_listing uuid)
returns boolean language sql stable security definer set search_path = public, pg_temp as $$
  select exists (
    select 1 from public.food_listings l
    join public.organization_members m on m.organization_id = l.donor_org_id
    where l.id = p_listing and m.user_id = auth.uid())
$$;

-- Receiver org member with a request on the listing, or the assigned volunteer.
create or replace function private.is_listing_participant(p_listing uuid)
returns boolean language sql stable security definer set search_path = public, pg_temp as $$
  select exists (
      select 1 from public.food_requests r
      join public.organization_members m on m.organization_id = r.receiver_org_id
      where r.listing_id = p_listing and m.user_id = auth.uid())
    or exists (
      select 1 from public.pickups p where p.listing_id = p_listing and p.volunteer_id = auth.uid())
$$;

create or replace function private.can_view_profile(p_target uuid)
returns boolean language sql stable security definer set search_path = public, pg_temp as $$
  select
    p_target = auth.uid()
    -- same organization
    or exists (
      select 1 from public.organization_members a
      join public.organization_members b on a.organization_id = b.organization_id
      where a.user_id = auth.uid() and b.user_id = p_target)
    -- volunteer <-> donor/receiver members on a shared pickup
    or exists (
      select 1 from public.pickups p
      join public.organization_members m on m.organization_id in (p.donor_org_id, p.receiver_org_id)
      where (p.volunteer_id = p_target and m.user_id = auth.uid())
         or (p.volunteer_id = auth.uid() and m.user_id = p_target))
    -- donor <-> receiver members on a shared pickup
    or exists (
      select 1 from public.pickups p
      join public.organization_members m1 on m1.organization_id in (p.donor_org_id, p.receiver_org_id)
      join public.organization_members m2 on m2.organization_id in (p.donor_org_id, p.receiver_org_id)
      where m1.user_id = auth.uid() and m2.user_id = p_target)
$$;

create or replace function private.log_audit(p_action text, p_entity_type text, p_entity_id uuid,
                                             p_listing_id uuid, p_metadata jsonb, p_is_demo boolean)
returns void language sql security definer set search_path = public, pg_temp as $$
  insert into public.audit_events (actor_id, action, entity_type, entity_id, listing_id, metadata, is_demo)
  values (auth.uid(), p_action, p_entity_type, p_entity_id, p_listing_id, coalesce(p_metadata, '{}'::jsonb),
          coalesce(p_is_demo, false))
$$;

create or replace function private.notify_user(p_user uuid, p_type text, p_title text, p_body text, p_link text)
returns void language sql security definer set search_path = public, pg_temp as $$
  insert into public.notifications (user_id, type, title, body, link)
  select p_user, p_type, p_title, p_body, p_link where p_user is not null
$$;

create or replace function private.notify_org(p_org uuid, p_type text, p_title text, p_body text, p_link text)
returns void language sql security definer set search_path = public, pg_temp as $$
  insert into public.notifications (user_id, type, title, body, link)
  select m.user_id, p_type, p_title, p_body, p_link
  from public.organization_members m where m.organization_id = p_org
$$;

revoke all on all functions in schema private from public;
grant execute on function
  private.haversine_km(double precision, double precision, double precision, double precision),
  private.is_admin(), private.is_demo_admin(), private.admin_can_see(boolean),
  private.is_org_member(uuid), private.is_listing_donor(uuid), private.is_listing_participant(uuid),
  private.can_view_profile(uuid), private.current_role_name()
to anon, authenticated, service_role;
-- Needed by the listing audit trigger, which runs as the calling client role.
-- (The private schema is not exposed through PostgREST.)
grant execute on function private.log_audit(text, text, uuid, uuid, jsonb, boolean) to authenticated;

-- ---------------------------------------------------------------------
-- updated_at maintenance
-- ---------------------------------------------------------------------
create or replace function private.touch_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end $$;

create trigger organizations_touch before update on public.organizations
  for each row execute function private.touch_updated_at();
create trigger profiles_touch before update on public.profiles
  for each row execute function private.touch_updated_at();
create trigger food_listings_touch before update on public.food_listings
  for each row execute function private.touch_updated_at();
create trigger food_requests_touch before update on public.food_requests
  for each row execute function private.touch_updated_at();
create trigger pickups_touch before update on public.pickups
  for each row execute function private.touch_updated_at();

-- ---------------------------------------------------------------------
-- New user -> profile (+ organization for donors/receivers)
-- Role is taken from signup metadata but can never be 'admin'.
-- ---------------------------------------------------------------------
create or replace function private.handle_new_user()
returns trigger language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_meta jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
  v_role text := coalesce(v_meta ->> 'role', 'volunteer');
  v_org_type text := coalesce(v_meta ->> 'org_type', 'other');
  v_org_id uuid;
begin
  if v_role not in ('donor', 'receiver', 'volunteer') then
    v_role := 'volunteer';
  end if;

  insert into public.profiles (id, full_name, email, role, phone)
  values (new.id, left(coalesce(v_meta ->> 'full_name', ''), 120), new.email, v_role,
          nullif(left(coalesce(v_meta ->> 'phone', ''), 30), ''));

  if v_role in ('donor', 'receiver') and coalesce(v_meta ->> 'skip_org', 'false') <> 'true' then
    if v_org_type not in ('restaurant', 'canteen', 'grocery', 'banquet_hall', 'community_kitchen',
                          'ngo', 'food_bank', 'community_org', 'other') then
      v_org_type := 'other';
    end if;

    insert into public.organizations (name, kind, org_type, address, city, latitude, longitude,
                                      has_refrigeration, has_freezer, capacity_meals, created_by)
    values (
      left(coalesce(nullif(trim(v_meta ->> 'org_name'), ''), 'Unnamed organization'), 120),
      v_role,
      v_org_type,
      left(v_meta ->> 'address', 300),
      left(v_meta ->> 'city', 80),
      case when private.try_float(v_meta ->> 'latitude') between -90 and 90
           then private.try_float(v_meta ->> 'latitude') end,
      case when private.try_float(v_meta ->> 'longitude') between -180 and 180
           then private.try_float(v_meta ->> 'longitude') end,
      coalesce((v_meta ->> 'has_refrigeration') = 'true', false),
      coalesce((v_meta ->> 'has_freezer') = 'true', false),
      greatest(0, least(100000, coalesce(private.try_float(v_meta ->> 'capacity_meals'), 0)::integer)),
      new.id)
    returning id into v_org_id;

    insert into public.organization_members (organization_id, user_id, member_role)
    values (v_org_id, new.id, 'owner');

    update public.profiles set organization_id = v_org_id where id = new.id;
  end if;

  return new;
end $$;

create trigger on_auth_user_created after insert on auth.users
  for each row execute function private.handle_new_user();

-- Defence in depth: end users can never change role / org / demo flag on their profile.
create or replace function private.guard_profile_update()
returns trigger language plpgsql as $$
begin
  if current_user in ('authenticated', 'anon') and (
       new.role is distinct from old.role
       or new.organization_id is distinct from old.organization_id
       or new.is_demo is distinct from old.is_demo
       or new.id is distinct from old.id) then
    raise exception 'You cannot change your role or organization.' using errcode = '42501';
  end if;
  return new;
end $$;
create trigger profiles_guard before update on public.profiles
  for each row execute function private.guard_profile_update();

-- ---------------------------------------------------------------------
-- Listing validation for direct (client) inserts/updates.
-- Security-definer RPCs run as the table owner and skip these checks.
-- ---------------------------------------------------------------------
create or replace function private.validate_listing()
returns trigger language plpgsql set search_path = public, pg_temp as $$
declare
  v_org public.organizations;
begin
  -- Only apply to writes coming straight from API clients (RPCs run as the owner).
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;

  if tg_op = 'INSERT' then
    select * into v_org from public.organizations where id = new.donor_org_id;
    new.status := 'available';
    new.created_by := auth.uid();
    new.is_demo := coalesce(v_org.is_demo, false);
    new.expiry_warned_at := null;
    new.moderation_note := null;
    if new.prepared_at is not null and new.prepared_at > now() + interval '5 minutes' then
      raise exception 'Preparation time cannot be in the future.';
    end if;
  end if;

  if new.safe_until <= now() then
    raise exception 'The safe-use deadline must be in the future.';
  end if;
  if new.pickup_end <= now() then
    raise exception 'The pickup window must end in the future.';
  end if;
  if new.pickup_end > new.safe_until then
    raise exception 'The pickup window cannot extend beyond the safe-use deadline.';
  end if;
  return new;
end $$;

create trigger food_listings_validate before insert or update on public.food_listings
  for each row execute function private.validate_listing();

create or replace function private.audit_listing_change()
returns trigger language plpgsql set search_path = public, pg_temp as $$
begin
  if current_user not in ('authenticated', 'anon') then
    return null;
  end if;
  if tg_op = 'INSERT' then
    perform private.log_audit('listing_created', 'food_listing', new.id, new.id,
      jsonb_build_object('title', new.title, 'meals', new.estimated_meals), new.is_demo);
  elsif tg_op = 'UPDATE' then
    perform private.log_audit('listing_updated', 'food_listing', new.id, new.id,
      jsonb_build_object('title', new.title), new.is_demo);
  end if;
  return null;
end $$;

create trigger food_listings_audit after insert or update on public.food_listings
  for each row execute function private.audit_listing_change();

-- ---------------------------------------------------------------------
-- Append-only audit trail
-- ---------------------------------------------------------------------
create or replace function private.audit_append_only()
returns trigger language plpgsql as $$
begin
  if coalesce(current_setting('foodbridge.allow_audit_purge', true), '') = 'on' then
    return old;
  end if;
  raise exception 'Audit events are append-only.' using errcode = '42501';
end $$;

create trigger audit_events_no_update before update or delete on public.audit_events
  for each row execute function private.audit_append_only();

-- ---------------------------------------------------------------------
-- Privileges. Supabase grants ALL to anon/authenticated by default;
-- we revoke and grant back only what clients may do directly.
-- Everything else goes through security-definer RPCs.
-- ---------------------------------------------------------------------
revoke all on public.organizations, public.profiles, public.organization_members, public.food_listings,
  public.food_requests, public.pickups, public.pickup_verifications, public.notifications,
  public.audit_events from anon, authenticated;

grant select on public.organizations, public.food_listings to anon, authenticated;
grant select on public.profiles, public.organization_members, public.food_requests, public.pickups,
  public.notifications, public.audit_events to authenticated;

grant update (name, org_type, address, city, latitude, longitude, has_refrigeration, has_freezer, capacity_meals)
  on public.organizations to authenticated;
grant update (full_name, phone) on public.profiles to authenticated;
grant insert (donor_org_id, title, description, category, diet, quantity, quantity_unit, estimated_meals,
  prepared_at, safe_until, pickup_start, pickup_end, storage_requirement, packaging, allergens,
  pickup_address, latitude, longitude, max_radius_km, handling_confirmed)
  on public.food_listings to authenticated;
grant update (title, description, category, diet, quantity, quantity_unit, estimated_meals,
  prepared_at, safe_until, pickup_start, pickup_end, storage_requirement, packaging, allergens,
  pickup_address, latitude, longitude, max_radius_km, handling_confirmed)
  on public.food_listings to authenticated;
grant update (read_at) on public.notifications to authenticated;
grant delete on public.notifications to authenticated;

-- ---------------------------------------------------------------------
-- Row Level Security
-- ---------------------------------------------------------------------
alter table public.organizations enable row level security;
alter table public.profiles enable row level security;
alter table public.organization_members enable row level security;
alter table public.food_listings enable row level security;
alter table public.food_requests enable row level security;
alter table public.pickups enable row level security;
alter table public.pickup_verifications enable row level security; -- no policies: unreadable via API
alter table public.notifications enable row level security;
alter table public.audit_events enable row level security;

-- Organizations: public directory (no personal data is stored here).
create policy organizations_read on public.organizations for select to anon, authenticated using (true);
create policy organizations_owner_update on public.organizations for update to authenticated
  using (exists (select 1 from public.organization_members m
                 where m.organization_id = id and m.user_id = auth.uid() and m.member_role = 'owner'))
  with check (exists (select 1 from public.organization_members m
                 where m.organization_id = id and m.user_id = auth.uid() and m.member_role = 'owner'));

-- Profiles
create policy profiles_read on public.profiles for select to authenticated
  using (private.can_view_profile(id) or private.admin_can_see(is_demo));
create policy profiles_self_update on public.profiles for update to authenticated
  using (id = auth.uid()) with check (id = auth.uid());

-- Organization members
create policy org_members_read on public.organization_members for select to authenticated
  using (user_id = auth.uid() or private.is_org_member(organization_id) or private.is_admin());

-- Listings
create policy listings_public_read on public.food_listings for select to anon, authenticated
  using (status = 'available' and safe_until > now());
create policy listings_party_read on public.food_listings for select to authenticated
  using (private.is_org_member(donor_org_id) or private.is_listing_participant(id)
         or private.admin_can_see(is_demo));
create policy listings_donor_insert on public.food_listings for insert to authenticated
  with check (
    private.is_org_member(donor_org_id)
    and private.current_role_name() = 'donor'
    and exists (select 1 from public.organizations o where o.id = donor_org_id and o.kind = 'donor'));
create policy listings_donor_update on public.food_listings for update to authenticated
  using (private.is_org_member(donor_org_id) and status = 'available')
  with check (private.is_org_member(donor_org_id) and status = 'available');

-- Requests
create policy requests_read on public.food_requests for select to authenticated
  using (private.is_org_member(receiver_org_id) or private.is_listing_donor(listing_id)
         or private.admin_can_see(is_demo));

-- Pickups
create policy pickups_read on public.pickups for select to authenticated
  using (private.is_org_member(donor_org_id) or private.is_org_member(receiver_org_id)
         or volunteer_id = auth.uid() or private.admin_can_see(is_demo));

-- Notifications
create policy notifications_own_read on public.notifications for select to authenticated
  using (user_id = auth.uid());
create policy notifications_own_update on public.notifications for update to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy notifications_own_delete on public.notifications for delete to authenticated
  using (user_id = auth.uid());

-- Audit events
create policy audit_read on public.audit_events for select to authenticated
  using (actor_id = auth.uid()
         or private.admin_can_see(is_demo)
         or (listing_id is not null and (private.is_listing_donor(listing_id)
                                         or private.is_listing_participant(listing_id))));

-- Realtime for notifications (when the publication exists, i.e. on Supabase).
do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    alter publication supabase_realtime add table public.notifications;
  end if;
end $$;

-- ===== 20261027000003_workflows.sql =====
-- =====================================================================
-- FoodBridge — transactional workflow RPCs (the rescue state machine)
--
-- Listing:  available -> reserved -> collected -> completed
--           available|reserved -> expired | cancelled | removed
-- Request:  pending -> accepted | rejected | cancelled ; accepted -> cancelled
-- Pickup:   scheduled -> assigned -> en_route -> arrived -> collected -> verified
--           (any pre-collection state) -> cancelled | expired
--
-- Lock order everywhere: listing row first, then request / pickup rows.
-- =====================================================================

-- ---------------------------------------------------------------------
-- Expiry synchronisation (idempotent). Called opportunistically by
-- clients and optionally by pg_cron. All other RPCs also check
-- deadlines directly, so correctness does not depend on this running.
-- ---------------------------------------------------------------------
create or replace function public.sync_expiry()
returns integer language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_listing record;
  v_count integer := 0;
begin
  -- Expire listings past their safe-use deadline that were never collected.
  for v_listing in
    select * from public.food_listings
    where status in ('available', 'reserved') and safe_until <= now()
    for update skip locked
  loop
    update public.food_listings set status = 'expired' where id = v_listing.id;

    update public.pickups set status = 'expired', cancelled_at = now()
    where listing_id = v_listing.id and status in ('scheduled', 'assigned', 'en_route', 'arrived');

    update public.food_requests
    set status = 'cancelled', decision_note = 'Listing expired before collection', decided_at = now()
    where listing_id = v_listing.id and status = 'pending';

    perform private.notify_org(v_listing.donor_org_id, 'listing_expired', 'Listing expired',
      format('"%s" passed its safe-use deadline without being collected.', v_listing.title),
      '/listings/' || v_listing.id);

    perform private.notify_org(r.receiver_org_id, 'listing_expired', 'Listing expired',
      format('"%s" expired before collection.', v_listing.title), '/listings/' || v_listing.id)
    from public.food_requests r
    where r.listing_id = v_listing.id and r.status in ('accepted');

    insert into public.audit_events (actor_id, action, entity_type, entity_id, listing_id, metadata, is_demo)
    values (null, 'listing_expired', 'food_listing', v_listing.id, v_listing.id,
            jsonb_build_object('title', v_listing.title, 'previous_status', v_listing.status), v_listing.is_demo);
    v_count := v_count + 1;
  end loop;

  -- Warn donors once when an unclaimed listing is within 60 minutes of its deadline.
  for v_listing in
    select * from public.food_listings
    where status = 'available' and expiry_warned_at is null
      and safe_until > now() and safe_until <= now() + interval '60 minutes'
    for update skip locked
  loop
    update public.food_listings set expiry_warned_at = now() where id = v_listing.id;
    perform private.notify_org(v_listing.donor_org_id, 'listing_expiring', 'Listing approaching expiry',
      format('"%s" reaches its safe-use deadline in under an hour and has not been reserved.', v_listing.title),
      '/listings/' || v_listing.id);
  end loop;

  return v_count;
end $$;

-- ---------------------------------------------------------------------
-- Receiver requests a listing
-- ---------------------------------------------------------------------
create or replace function public.request_listing(p_listing_id uuid, p_message text default null)
returns uuid language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_uid uuid := auth.uid();
  v_profile public.profiles;
  v_org public.organizations;
  v_listing public.food_listings;
  v_distance double precision;
  v_request_id uuid;
begin
  if v_uid is null then
    raise exception 'Please sign in to request food.' using errcode = '28000';
  end if;

  select * into v_profile from public.profiles where id = v_uid;
  if v_profile.role is distinct from 'receiver' then
    raise exception 'Only receiver organizations can request food.' using errcode = '42501';
  end if;

  select * into v_org from public.organizations where id = v_profile.organization_id;
  if v_org.id is null or not private.is_org_member(v_org.id) then
    raise exception 'Your account is not linked to a receiver organization.' using errcode = '42501';
  end if;
  if v_org.verification_status <> 'verified' then
    raise exception 'Your organization must be verified by an administrator before requesting food.'
      using errcode = '42501';
  end if;

  select * into v_listing from public.food_listings where id = p_listing_id for update;
  if v_listing.id is null then
    raise exception 'Listing not found.';
  end if;
  if v_listing.is_demo <> v_org.is_demo then
    raise exception 'Demo organizations can only interact with demo listings (and vice versa).';
  end if;
  if v_listing.safe_until <= now() then
    raise exception 'This listing has passed its safe-use deadline and can no longer be requested.';
  end if;
  if v_listing.status <> 'available' then
    raise exception 'This listing is no longer available for requests.';
  end if;
  if v_listing.pickup_end <= now() then
    raise exception 'The pickup window for this listing has closed.';
  end if;

  if v_listing.storage_requirement = 'refrigerated' and not (v_org.has_refrigeration or v_org.has_freezer) then
    raise exception 'This food requires refrigerated storage, which your organization has not declared.';
  end if;
  if v_listing.storage_requirement = 'frozen' and not v_org.has_freezer then
    raise exception 'This food requires frozen storage, which your organization has not declared.';
  end if;
  if v_org.capacity_meals < v_listing.estimated_meals then
    raise exception 'This listing (% meals) exceeds your declared handling capacity (% meals).',
      v_listing.estimated_meals, v_org.capacity_meals;
  end if;

  v_distance := private.haversine_km(v_org.latitude, v_org.longitude, v_listing.latitude, v_listing.longitude);
  if v_distance is not null and v_distance > v_listing.max_radius_km then
    raise exception 'Your organization is % km away, outside the donor''s % km pickup radius.',
      round(v_distance::numeric, 1), v_listing.max_radius_km;
  end if;

  begin
    insert into public.food_requests (listing_id, receiver_org_id, requested_by, requested_quantity,
                                      message, distance_km, is_demo)
    values (v_listing.id, v_org.id, v_uid, v_listing.quantity, nullif(left(trim(p_message), 500), ''),
            round(v_distance::numeric, 2), v_listing.is_demo)
    returning id into v_request_id;
  exception when unique_violation then
    raise exception 'Your organization already has an open request for this listing.';
  end;

  perform private.notify_org(v_listing.donor_org_id, 'request_new', 'New food request',
    format('%s requested "%s".', v_org.name, v_listing.title), '/requests');
  perform private.log_audit('request_submitted', 'food_request', v_request_id, v_listing.id,
    jsonb_build_object('receiver_org', v_org.name, 'distance_km', round(v_distance::numeric, 2)), v_listing.is_demo);

  return v_request_id;
end $$;

-- ---------------------------------------------------------------------
-- Donor accepts / rejects a request (atomic; prevents double booking)
-- ---------------------------------------------------------------------
create or replace function public.respond_to_request(p_request_id uuid, p_accept boolean, p_note text default null)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_uid uuid := auth.uid();
  v_listing_id uuid;
  v_listing public.food_listings;
  v_req public.food_requests;
  v_org public.organizations;
  v_other record;
  v_pickup_id uuid;
begin
  if v_uid is null then
    raise exception 'Please sign in.' using errcode = '28000';
  end if;

  select listing_id into v_listing_id from public.food_requests where id = p_request_id;
  if v_listing_id is null then
    raise exception 'Request not found.';
  end if;

  -- Lock the listing first: concurrent accepts on the same listing serialise here.
  select * into v_listing from public.food_listings where id = v_listing_id for update;
  if not private.is_org_member(v_listing.donor_org_id) then
    raise exception 'Only the donor organization can respond to this request.' using errcode = '42501';
  end if;

  select * into v_req from public.food_requests where id = p_request_id for update;
  if v_req.status <> 'pending' then
    raise exception 'This request has already been %.', v_req.status;
  end if;

  select * into v_org from public.organizations where id = v_req.receiver_org_id;

  if not p_accept then
    update public.food_requests
    set status = 'rejected', decision_note = nullif(left(trim(p_note), 500), ''), decided_by = v_uid, decided_at = now()
    where id = v_req.id;
    perform private.notify_org(v_req.receiver_org_id, 'request_rejected', 'Request declined',
      format('Your request for "%s" was declined.', v_listing.title), '/requests');
    perform private.log_audit('request_rejected', 'food_request', v_req.id, v_listing.id,
      jsonb_build_object('receiver_org', v_org.name), v_listing.is_demo);
    return jsonb_build_object('request_id', v_req.id, 'status', 'rejected');
  end if;

  if v_listing.safe_until <= now() or v_listing.pickup_end <= now() then
    raise exception 'This listing has expired or its pickup window has closed; it cannot be accepted.';
  end if;
  if v_listing.status <> 'available' then
    raise exception 'This listing is already reserved or closed.';
  end if;
  if v_org.verification_status <> 'verified' then
    raise exception 'The receiving organization is no longer verified.';
  end if;

  update public.food_requests
  set status = 'accepted', decision_note = nullif(left(trim(p_note), 500), ''), decided_by = v_uid, decided_at = now()
  where id = v_req.id;

  update public.food_listings set status = 'reserved' where id = v_listing.id;

  insert into public.pickups (listing_id, request_id, donor_org_id, receiver_org_id, is_demo)
  values (v_listing.id, v_req.id, v_listing.donor_org_id, v_req.receiver_org_id, v_listing.is_demo)
  returning id into v_pickup_id;

  -- Close out competing requests; they never consumed inventory.
  for v_other in
    select r.id, r.receiver_org_id from public.food_requests r
    where r.listing_id = v_listing.id and r.status = 'pending' and r.id <> v_req.id
    for update
  loop
    update public.food_requests
    set status = 'rejected', decision_note = 'Another organization was selected for this listing.',
        decided_by = v_uid, decided_at = now()
    where id = v_other.id;
    perform private.notify_org(v_other.receiver_org_id, 'request_rejected', 'Request not selected',
      format('"%s" was reserved by another organization.', v_listing.title), '/requests');
    perform private.log_audit('request_rejected', 'food_request', v_other.id, v_listing.id,
      jsonb_build_object('reason', 'another_request_accepted'), v_listing.is_demo);
  end loop;

  perform private.notify_org(v_req.receiver_org_id, 'request_accepted', 'Request accepted',
    format('Your request for "%s" was accepted. Arrange pickup before %s UTC.', v_listing.title,
           to_char(v_listing.pickup_end at time zone 'UTC', 'DD Mon HH24:MI')), '/pickups');
  perform private.log_audit('request_accepted', 'food_request', v_req.id, v_listing.id,
    jsonb_build_object('receiver_org', v_org.name, 'pickup_id', v_pickup_id), v_listing.is_demo);

  return jsonb_build_object('request_id', v_req.id, 'status', 'accepted', 'pickup_id', v_pickup_id);
end $$;

-- ---------------------------------------------------------------------
-- Receiver cancels their own request (pending, or accepted before collection)
-- ---------------------------------------------------------------------
create or replace function public.cancel_request(p_request_id uuid)
returns void language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_listing_id uuid;
  v_listing public.food_listings;
  v_req public.food_requests;
  v_pickup public.pickups;
begin
  select listing_id into v_listing_id from public.food_requests where id = p_request_id;
  if v_listing_id is null then
    raise exception 'Request not found.';
  end if;
  select * into v_listing from public.food_listings where id = v_listing_id for update;
  select * into v_req from public.food_requests where id = p_request_id for update;

  if not private.is_org_member(v_req.receiver_org_id) then
    raise exception 'Only the requesting organization can cancel this request.' using errcode = '42501';
  end if;
  if v_req.status not in ('pending', 'accepted') then
    raise exception 'This request is already %.', v_req.status;
  end if;

  if v_req.status = 'accepted' then
    select * into v_pickup from public.pickups where request_id = v_req.id for update;
    if v_pickup.status not in ('scheduled', 'assigned', 'en_route', 'arrived') then
      raise exception 'This pickup has already been collected and cannot be cancelled.';
    end if;
    update public.pickups set status = 'cancelled', cancelled_at = now() where id = v_pickup.id;
    update public.pickup_verifications set invalidated_at = now()
      where pickup_id = v_pickup.id and used_at is null and invalidated_at is null;
    update public.food_listings
    set status = case when safe_until > now() and pickup_end > now() then 'available' else 'expired' end
    where id = v_listing.id;
    perform private.notify_user(v_pickup.volunteer_id, 'pickup_updated', 'Pickup cancelled',
      format('The pickup for "%s" was cancelled by the receiver.', v_listing.title), '/pickups');
  end if;

  update public.food_requests set status = 'cancelled', decided_at = now() where id = v_req.id;

  perform private.notify_org(v_listing.donor_org_id, 'request_cancelled', 'Request withdrawn',
    format('A receiver withdrew its request for "%s".', v_listing.title), '/listings/' || v_listing.id);
  perform private.log_audit('request_cancelled', 'food_request', v_req.id, v_listing.id,
    jsonb_build_object('previous_status', v_req.status), v_listing.is_demo);
end $$;

-- ---------------------------------------------------------------------
-- Donor cancels a listing (before collection)
-- ---------------------------------------------------------------------
create or replace function public.cancel_listing(p_listing_id uuid, p_reason text default null)
returns void language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_listing public.food_listings;
  v_req record;
begin
  select * into v_listing from public.food_listings where id = p_listing_id for update;
  if v_listing.id is null then
    raise exception 'Listing not found.';
  end if;
  if not private.is_org_member(v_listing.donor_org_id) then
    raise exception 'Only the donor organization can cancel this listing.' using errcode = '42501';
  end if;
  if v_listing.status not in ('available', 'reserved') then
    raise exception 'A % listing cannot be cancelled.', v_listing.status;
  end if;

  update public.food_listings set status = 'cancelled' where id = v_listing.id;

  for v_req in
    select id, receiver_org_id from public.food_requests
    where listing_id = v_listing.id and status in ('pending', 'accepted') for update
  loop
    update public.food_requests set status = 'cancelled', decision_note = 'Listing cancelled by donor',
      decided_at = now() where id = v_req.id;
    perform private.notify_org(v_req.receiver_org_id, 'listing_cancelled', 'Listing cancelled',
      format('"%s" was cancelled by the donor.', v_listing.title), '/requests');
  end loop;

  perform private.notify_user(p.volunteer_id, 'pickup_updated', 'Pickup cancelled',
    format('The pickup for "%s" was cancelled by the donor.', v_listing.title), '/pickups')
  from public.pickups p where p.listing_id = v_listing.id and p.status in ('scheduled', 'assigned', 'en_route', 'arrived');

  update public.pickup_verifications v set invalidated_at = now()
  from public.pickups p
  where v.pickup_id = p.id and p.listing_id = v_listing.id and v.used_at is null and v.invalidated_at is null;

  update public.pickups set status = 'cancelled', cancelled_at = now()
  where listing_id = v_listing.id and status in ('scheduled', 'assigned', 'en_route', 'arrived');

  perform private.log_audit('listing_cancelled', 'food_listing', v_listing.id, v_listing.id,
    jsonb_build_object('reason', nullif(left(trim(p_reason), 300), '')), v_listing.is_demo);
end $$;

-- ---------------------------------------------------------------------
-- Volunteer directory for receivers arranging collection
-- ---------------------------------------------------------------------
create or replace function public.list_volunteers()
returns table (id uuid, full_name text)
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_profile public.profiles;
begin
  select * into v_profile from public.profiles where profiles.id = auth.uid();
  if coalesce(v_profile.role, '') not in ('receiver', 'admin') then
    raise exception 'Only receiver organizations can view volunteers.' using errcode = '42501';
  end if;
  return query
    select p.id, p.full_name from public.profiles p
    where p.role = 'volunteer' and p.is_demo = v_profile.is_demo
    order by p.full_name;
end $$;

-- ---------------------------------------------------------------------
-- Receiver assigns (or unassigns) a volunteer to a pickup
-- ---------------------------------------------------------------------
create or replace function public.assign_volunteer(p_pickup_id uuid, p_volunteer_id uuid)
returns void language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_pickup public.pickups;
  v_listing public.food_listings;
  v_volunteer public.profiles;
begin
  select * into v_pickup from public.pickups where id = p_pickup_id;
  if v_pickup.id is null then
    raise exception 'Pickup not found.';
  end if;
  select * into v_listing from public.food_listings where id = v_pickup.listing_id for update;
  select * into v_pickup from public.pickups where id = p_pickup_id for update;

  if not private.is_org_member(v_pickup.receiver_org_id) then
    raise exception 'Only the receiving organization can assign volunteers.' using errcode = '42501';
  end if;
  if v_pickup.status not in ('scheduled', 'assigned') then
    raise exception 'Volunteers can only be changed before the pickup is under way.';
  end if;

  if p_volunteer_id is null then
    update public.pickups set volunteer_id = null, status = 'scheduled', assigned_at = null where id = v_pickup.id;
    perform private.notify_user(v_pickup.volunteer_id, 'pickup_updated', 'Pickup unassigned',
      format('You were removed from the pickup for "%s".', v_listing.title), '/pickups');
  else
    select * into v_volunteer from public.profiles where id = p_volunteer_id;
    if v_volunteer.id is null or v_volunteer.role <> 'volunteer' then
      raise exception 'Selected user is not a volunteer.';
    end if;
    if v_volunteer.is_demo <> v_pickup.is_demo then
      raise exception 'Demo pickups can only be assigned to demo volunteers (and vice versa).';
    end if;
    update public.pickups set volunteer_id = v_volunteer.id, status = 'assigned', assigned_at = now()
    where id = v_pickup.id;
    perform private.notify_user(v_volunteer.id, 'pickup_assigned', 'New pickup assigned',
      format('You have been assigned to collect "%s".', v_listing.title), '/pickups');
    perform private.notify_org(v_pickup.donor_org_id, 'pickup_updated', 'Volunteer assigned',
      format('%s will collect "%s".', coalesce(nullif(v_volunteer.full_name, ''), 'A volunteer'), v_listing.title),
      '/pickups');
  end if;

  perform private.log_audit('pickup_assigned', 'pickup', v_pickup.id, v_listing.id,
    jsonb_build_object('volunteer_id', p_volunteer_id), v_listing.is_demo);
end $$;

-- ---------------------------------------------------------------------
-- Collector reports progress (en_route / arrived)
-- ---------------------------------------------------------------------
create or replace function public.update_pickup_progress(p_pickup_id uuid, p_status text)
returns void language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_pickup public.pickups;
  v_listing public.food_listings;
begin
  select * into v_pickup from public.pickups where id = p_pickup_id;
  if v_pickup.id is null then
    raise exception 'Pickup not found.';
  end if;
  select * into v_listing from public.food_listings where id = v_pickup.listing_id for update;
  select * into v_pickup from public.pickups where id = p_pickup_id for update;

  -- coalesce: volunteer_id may be NULL, and NULL logic must never grant access.
  if not coalesce(v_pickup.volunteer_id = auth.uid()
          or (v_pickup.volunteer_id is null and private.is_org_member(v_pickup.receiver_org_id)), false) then
    raise exception 'Only the assigned collector can update this pickup.' using errcode = '42501';
  end if;
  if v_listing.safe_until <= now() then
    raise exception 'This listing has passed its safe-use deadline.';
  end if;

  if p_status = 'en_route' and v_pickup.status in ('scheduled', 'assigned') then
    update public.pickups set status = 'en_route', en_route_at = now() where id = v_pickup.id;
  elsif p_status = 'arrived' and v_pickup.status in ('scheduled', 'assigned', 'en_route') then
    update public.pickups set status = 'arrived', arrived_at = now() where id = v_pickup.id;
  else
    raise exception 'Cannot move a % pickup to %.', v_pickup.status, p_status;
  end if;

  perform private.notify_org(v_pickup.donor_org_id, 'pickup_updated', 'Pickup update',
    format('Collector for "%s" is %s.', v_listing.title, replace(p_status, '_', ' ')), '/pickups');
  if v_pickup.volunteer_id is not null then
    perform private.notify_org(v_pickup.receiver_org_id, 'pickup_updated', 'Pickup update',
      format('Volunteer for "%s" is %s.', v_listing.title, replace(p_status, '_', ' ')), '/pickups');
  end if;
  perform private.log_audit('pickup_status_updated', 'pickup', v_pickup.id, v_listing.id,
    jsonb_build_object('status', p_status), v_listing.is_demo);
end $$;

-- ---------------------------------------------------------------------
-- Donor generates a one-time handover code. Only a bcrypt hash is stored;
-- the plaintext is returned once to the donor. Generating a new code
-- invalidates any previous unused code.
-- ---------------------------------------------------------------------
create or replace function public.generate_handover_code(p_pickup_id uuid)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_pickup public.pickups;
  v_listing public.food_listings;
  v_code text;
  v_expires timestamptz;
  v_recent integer;
begin
  select * into v_pickup from public.pickups where id = p_pickup_id;
  if v_pickup.id is null then
    raise exception 'Pickup not found.';
  end if;
  select * into v_listing from public.food_listings where id = v_pickup.listing_id for update;
  select * into v_pickup from public.pickups where id = p_pickup_id for update;

  if not private.is_org_member(v_pickup.donor_org_id) then
    raise exception 'Only the donor organization can generate a handover code.' using errcode = '42501';
  end if;
  if v_pickup.status not in ('scheduled', 'assigned', 'en_route', 'arrived') then
    raise exception 'A handover code cannot be generated for a % pickup.', v_pickup.status;
  end if;
  if v_listing.safe_until <= now() then
    raise exception 'This listing has passed its safe-use deadline.';
  end if;

  select count(*) into v_recent from public.pickup_verifications
  where pickup_id = v_pickup.id and created_at > now() - interval '1 hour';
  if v_recent >= 10 then
    raise exception 'Too many codes generated for this pickup. Please wait before generating another.';
  end if;

  update public.pickup_verifications set invalidated_at = now()
  where pickup_id = v_pickup.id and used_at is null and invalidated_at is null;

  v_code := lpad((((('x' || encode(extensions.gen_random_bytes(4), 'hex'))::bit(32)::bigint) % 1000000))::text, 6, '0');
  v_expires := least(now() + interval '30 minutes', v_listing.safe_until);

  insert into public.pickup_verifications (pickup_id, code_hash, expires_at, created_by)
  values (v_pickup.id, extensions.crypt(v_code, extensions.gen_salt('bf', 8)), v_expires, auth.uid());

  perform private.log_audit('handover_code_generated', 'pickup', v_pickup.id, v_listing.id,
    jsonb_build_object('expires_at', v_expires), v_listing.is_demo);

  return jsonb_build_object('code', v_code, 'expires_at', v_expires);
end $$;

-- ---------------------------------------------------------------------
-- Collector (assigned volunteer or receiver member) enters the code at
-- the physical handover. Failed attempts are counted and persisted, so
-- this returns a result object instead of raising for wrong codes.
-- ---------------------------------------------------------------------
create or replace function public.verify_handover_code(p_pickup_id uuid, p_code text)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_uid uuid := auth.uid();
  v_pickup public.pickups;
  v_listing public.food_listings;
  v_ver public.pickup_verifications;
begin
  select * into v_pickup from public.pickups where id = p_pickup_id;
  if v_pickup.id is null then
    raise exception 'Pickup not found.';
  end if;
  select * into v_listing from public.food_listings where id = v_pickup.listing_id for update;
  select * into v_pickup from public.pickups where id = p_pickup_id for update;

  if not (coalesce(v_pickup.volunteer_id = v_uid, false) or private.is_org_member(v_pickup.receiver_org_id)) then
    raise exception 'Only the assigned volunteer or the receiving organization can verify this handover.'
      using errcode = '42501';
  end if;
  if v_pickup.status in ('collected', 'verified') then
    return jsonb_build_object('ok', false, 'reason', 'already_completed',
      'message', 'This handover has already been verified. Codes cannot be reused.');
  end if;
  if v_pickup.status not in ('scheduled', 'assigned', 'en_route', 'arrived') then
    return jsonb_build_object('ok', false, 'reason', 'invalid_state',
      'message', format('This pickup is %s.', v_pickup.status));
  end if;
  if v_listing.safe_until <= now() then
    return jsonb_build_object('ok', false, 'reason', 'listing_expired',
      'message', 'This listing has passed its safe-use deadline.');
  end if;
  if p_code is null or p_code !~ '^[0-9]{6}$' then
    return jsonb_build_object('ok', false, 'reason', 'format', 'message', 'Enter the 6-digit code.');
  end if;

  select * into v_ver from public.pickup_verifications
  where pickup_id = v_pickup.id and used_at is null and invalidated_at is null
  order by created_at desc limit 1
  for update;

  if v_ver.id is null then
    return jsonb_build_object('ok', false, 'reason', 'no_active_code',
      'message', 'No active code. Ask the donor to generate a handover code.');
  end if;
  if v_ver.expires_at <= now() then
    return jsonb_build_object('ok', false, 'reason', 'expired',
      'message', 'This code has expired. Ask the donor to generate a new one.');
  end if;
  if v_ver.attempts >= v_ver.max_attempts then
    return jsonb_build_object('ok', false, 'reason', 'locked',
      'message', 'Too many incorrect attempts. Ask the donor to generate a new code.');
  end if;

  if extensions.crypt(p_code, v_ver.code_hash) <> v_ver.code_hash then
    update public.pickup_verifications set attempts = attempts + 1 where id = v_ver.id;
    perform private.log_audit('handover_verification_failed', 'pickup', v_pickup.id, v_listing.id,
      jsonb_build_object('attempt', v_ver.attempts + 1), v_listing.is_demo);
    return jsonb_build_object('ok', false, 'reason', 'mismatch',
      'message', 'Incorrect code.', 'attempts_remaining', v_ver.max_attempts - v_ver.attempts - 1);
  end if;

  update public.pickup_verifications set used_at = now(), used_by = v_uid where id = v_ver.id;
  update public.pickups set status = 'collected', collected_at = now(), collected_by = v_uid where id = v_pickup.id;
  update public.food_listings set status = 'collected' where id = v_listing.id;

  perform private.notify_org(v_pickup.donor_org_id, 'pickup_updated', 'Handover verified',
    format('"%s" was collected. The handover code was verified.', v_listing.title), '/pickups');
  perform private.notify_org(v_pickup.receiver_org_id, 'pickup_updated', 'Food collected',
    format('"%s" was collected. Confirm receipt once it arrives.', v_listing.title), '/pickups');
  perform private.log_audit('collection_recorded', 'pickup', v_pickup.id, v_listing.id,
    jsonb_build_object('method', 'handover_code'), v_listing.is_demo);

  return jsonb_build_object('ok', true, 'status', 'collected', 'message', 'Handover verified. Food marked as collected.');
end $$;

-- ---------------------------------------------------------------------
-- Receiver confirms receipt -> verified rescue (counts in impact metrics)
-- ---------------------------------------------------------------------
create or replace function public.confirm_receipt(p_pickup_id uuid)
returns void language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_pickup public.pickups;
  v_listing public.food_listings;
begin
  select * into v_pickup from public.pickups where id = p_pickup_id;
  if v_pickup.id is null then
    raise exception 'Pickup not found.';
  end if;
  select * into v_listing from public.food_listings where id = v_pickup.listing_id for update;
  select * into v_pickup from public.pickups where id = p_pickup_id for update;

  if not private.is_org_member(v_pickup.receiver_org_id) then
    raise exception 'Only the receiving organization can confirm receipt.' using errcode = '42501';
  end if;
  if v_pickup.status <> 'collected' then
    raise exception 'Receipt can only be confirmed after a verified handover (pickup is %).', v_pickup.status;
  end if;

  update public.pickups set status = 'verified', verified_at = now(), verified_by = auth.uid() where id = v_pickup.id;
  update public.food_listings set status = 'completed' where id = v_listing.id;

  perform private.notify_org(v_pickup.donor_org_id, 'pickup_verified', 'Rescue verified',
    format('"%s" was received and verified. %s meals rescued.', v_listing.title, v_listing.estimated_meals), '/impact');
  perform private.notify_user(v_pickup.volunteer_id, 'pickup_verified', 'Rescue verified',
    format('Delivery of "%s" was confirmed. Thank you!', v_listing.title), '/pickups');
  perform private.log_audit('verification_completed', 'pickup', v_pickup.id, v_listing.id,
    jsonb_build_object('meals', v_listing.estimated_meals), v_listing.is_demo);
end $$;

-- ---------------------------------------------------------------------
-- Admin moderation
-- ---------------------------------------------------------------------
create or replace function public.admin_set_org_verification(p_org_id uuid, p_status text, p_note text default null)
returns void language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_org public.organizations;
begin
  select * into v_org from public.organizations where id = p_org_id for update;
  if v_org.id is null then
    raise exception 'Organization not found.';
  end if;
  if not private.admin_can_see(v_org.is_demo) then
    raise exception 'Administrator access required.' using errcode = '42501';
  end if;
  if p_status not in ('pending', 'verified', 'rejected') then
    raise exception 'Invalid verification status.';
  end if;

  update public.organizations set verification_status = p_status,
    verification_note = nullif(left(trim(p_note), 500), '') where id = v_org.id;

  perform private.notify_org(v_org.id, 'organization_verification',
    case p_status when 'verified' then 'Organization verified' when 'rejected' then 'Verification declined'
                  else 'Verification reset' end,
    case p_status when 'verified' then format('%s is now verified on FoodBridge.', v_org.name)
                  else format('%s verification status: %s.', v_org.name, p_status) end,
    '/profile');
  perform private.log_audit('organization_' || p_status, 'organization', v_org.id, null,
    jsonb_build_object('name', v_org.name, 'note', p_note), v_org.is_demo);
end $$;

create or replace function public.admin_remove_listing(p_listing_id uuid, p_note text)
returns void language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_listing public.food_listings;
  v_req record;
begin
  select * into v_listing from public.food_listings where id = p_listing_id for update;
  if v_listing.id is null then
    raise exception 'Listing not found.';
  end if;
  if not private.admin_can_see(v_listing.is_demo) then
    raise exception 'Administrator access required.' using errcode = '42501';
  end if;
  if v_listing.status not in ('available', 'reserved') then
    raise exception 'Only open listings can be removed (this one is %).', v_listing.status;
  end if;

  update public.food_listings set status = 'removed', moderation_note = nullif(left(trim(p_note), 500), '')
  where id = v_listing.id;

  for v_req in
    select id, receiver_org_id from public.food_requests
    where listing_id = v_listing.id and status in ('pending', 'accepted') for update
  loop
    update public.food_requests set status = 'cancelled', decision_note = 'Listing removed by moderator',
      decided_at = now() where id = v_req.id;
    perform private.notify_org(v_req.receiver_org_id, 'listing_cancelled', 'Listing removed',
      format('"%s" was removed by a moderator.', v_listing.title), '/requests');
  end loop;
  update public.pickup_verifications v set invalidated_at = now()
  from public.pickups p
  where v.pickup_id = p.id and p.listing_id = v_listing.id and v.used_at is null and v.invalidated_at is null;
  update public.pickups set status = 'cancelled', cancelled_at = now()
  where listing_id = v_listing.id and status in ('scheduled', 'assigned', 'en_route', 'arrived');

  perform private.notify_org(v_listing.donor_org_id, 'listing_removed', 'Listing removed by moderator',
    format('"%s" was removed. Note: %s', v_listing.title, coalesce(nullif(trim(p_note), ''), 'none')),
    '/listings/' || v_listing.id);
  perform private.log_audit('listing_removed', 'food_listing', v_listing.id, v_listing.id,
    jsonb_build_object('note', p_note), v_listing.is_demo);
end $$;

-- ---------------------------------------------------------------------
-- Impact analytics. Only verified handovers count as rescued food.
-- p_scope: 'mine' (caller's organization / volunteer work) or 'platform'.
-- ---------------------------------------------------------------------
create or replace function public.get_impact_stats(p_scope text default 'mine')
returns jsonb language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_profile public.profiles;
  v_result jsonb;
  v_co2_factor constant numeric := 2.5; -- kg CO2e per kg of food (estimate; see README)
begin
  select * into v_profile from public.profiles where id = auth.uid();
  if v_profile.id is null then
    raise exception 'Please sign in.' using errcode = '28000';
  end if;

  with scoped as (
    select l.*
    from public.food_listings l
    where case
      when p_scope = 'platform' or v_profile.role = 'admin' then true
      when v_profile.role = 'donor' then l.donor_org_id = v_profile.organization_id
      when v_profile.role = 'receiver' then exists (
        select 1 from public.pickups p where p.listing_id = l.id and p.receiver_org_id = v_profile.organization_id)
      when v_profile.role = 'volunteer' then exists (
        select 1 from public.pickups p where p.listing_id = l.id and p.volunteer_id = v_profile.id)
      else false end
  ),
  verified as (
    -- one verified pickup per listing by construction (one accepted request per listing)
    select s.*, p.verified_at
    from scoped s
    join public.pickups p on p.listing_id = s.id and p.status = 'verified'
    where s.status = 'completed'
  ),
  totals as (
    select
      count(*) as total_listings,
      coalesce(sum(estimated_meals), 0) as listed_meals,
      coalesce(sum(estimated_meals) filter (where status in ('collected', 'completed')), 0) as collected_meals,
      count(*) filter (where status = 'expired' or (status in ('available', 'reserved') and safe_until <= now())) as expired_listings,
      count(*) filter (where status = 'cancelled') as cancelled_listings,
      count(*) filter (where status = 'available' and safe_until > now()) as active_listings,
      count(*) filter (where status in ('reserved', 'collected') and safe_until > now() or status = 'collected') as in_progress,
      count(*) filter (where status in ('completed', 'expired', 'cancelled', 'removed')
                       or (status in ('available', 'reserved') and safe_until <= now())) as closed_listings,
      count(*) filter (where is_demo) as demo_listings
    from scoped
  ),
  vtotals as (
    select count(*) as successful_pickups,
           coalesce(sum(estimated_meals), 0) as verified_meals,
           coalesce(sum(quantity) filter (where quantity_unit = 'kg'), 0) as verified_kg,
           coalesce(sum(quantity) filter (where quantity_unit = 'litres'), 0) as verified_litres
    from verified
  )
  select jsonb_build_object(
    'scope', case when p_scope = 'platform' or v_profile.role = 'admin' then 'platform' else 'mine' end,
    'total_listings', t.total_listings,
    'listed_meals', t.listed_meals,
    'collected_meals', t.collected_meals,
    'verified_meals', v.verified_meals,
    'verified_kg', v.verified_kg,
    'verified_litres', v.verified_litres,
    'co2e_kg_estimate', round(v.verified_kg * v_co2_factor, 1),
    'co2e_factor', v_co2_factor,
    'expired_listings', t.expired_listings,
    'cancelled_listings', t.cancelled_listings,
    'active_listings', t.active_listings,
    'in_progress', t.in_progress,
    'successful_pickups', v.successful_pickups,
    'completion_rate', case when t.closed_listings = 0 then null
                            else round(v.successful_pickups::numeric / t.closed_listings * 100, 1) end,
    'demo_listings', t.demo_listings,
    'timeseries', coalesce((
      select jsonb_agg(jsonb_build_object('day', d.day, 'verified_meals', d.verified_meals, 'listed_meals', d.listed_meals)
                       order by d.day)
      from (
        select g.day::date as day,
          coalesce((select sum(estimated_meals) from verified where verified_at::date = g.day::date), 0) as verified_meals,
          coalesce((select sum(estimated_meals) from scoped where created_at::date = g.day::date), 0) as listed_meals
        from generate_series((now() - interval '29 days')::date, now()::date, interval '1 day') g(day)
      ) d), '[]'::jsonb),
    'categories', coalesce((
      select jsonb_agg(jsonb_build_object('category', c.category, 'verified_meals', c.verified_meals, 'listings', c.listings)
                       order by c.verified_meals desc)
      from (
        select s.category, count(*) as listings,
               coalesce(sum(s.estimated_meals) filter (where s.status = 'completed'), 0) as verified_meals
        from scoped s group by s.category
      ) c), '[]'::jsonb),
    'status_distribution', coalesce((
      select jsonb_agg(jsonb_build_object('status', x.status, 'count', x.n))
      from (
        select case when status in ('available', 'reserved') and safe_until <= now() then 'expired' else status end as status,
               count(*) as n
        from scoped group by 1
      ) x), '[]'::jsonb),
    'top_donors', coalesce((
      select jsonb_agg(jsonb_build_object('name', o.name, 'listings', d.listings, 'verified_meals', d.verified_meals)
                       order by d.verified_meals desc, d.listings desc)
      from (
        select s.donor_org_id, count(*) as listings,
               coalesce(sum(s.estimated_meals) filter (where s.status = 'completed'), 0) as verified_meals
        from scoped s group by s.donor_org_id order by 3 desc, 2 desc limit 6
      ) d join public.organizations o on o.id = d.donor_org_id), '[]'::jsonb)
  ) into v_result
  from totals t, vtotals v;

  return v_result;
end $$;

-- ---------------------------------------------------------------------
-- Function privileges: callable by signed-in users only.
-- ---------------------------------------------------------------------
revoke all on function
  public.sync_expiry(), public.request_listing(uuid, text), public.respond_to_request(uuid, boolean, text),
  public.cancel_request(uuid), public.cancel_listing(uuid, text), public.list_volunteers(),
  public.assign_volunteer(uuid, uuid), public.update_pickup_progress(uuid, text),
  public.generate_handover_code(uuid), public.verify_handover_code(uuid, text), public.confirm_receipt(uuid),
  public.admin_set_org_verification(uuid, text, text), public.admin_remove_listing(uuid, text),
  public.get_impact_stats(text)
from public, anon;

grant execute on function
  public.sync_expiry(), public.request_listing(uuid, text), public.respond_to_request(uuid, boolean, text),
  public.cancel_request(uuid), public.cancel_listing(uuid, text), public.list_volunteers(),
  public.assign_volunteer(uuid, uuid), public.update_pickup_progress(uuid, text),
  public.generate_handover_code(uuid), public.verify_handover_code(uuid, text), public.confirm_receipt(uuid),
  public.admin_set_org_verification(uuid, text, text), public.admin_remove_listing(uuid, text),
  public.get_impact_stats(text)
to authenticated, service_role;

-- ===== 20261027000004_demo_seed.sql =====
-- =====================================================================
-- FoodBridge — demo data (fictional organizations around Vijayawada /
-- VIT-AP). Every demo record has is_demo = true and is isolated from
-- real activity by the workflow RPCs. Callable only with the
-- service-role key (scripts/seed-demo.mjs), never from the browser.
-- =====================================================================

-- Notify full admins when a new organization signs up and needs review.
create or replace function private.notify_admins_new_org()
returns trigger language plpgsql security definer set search_path = public, pg_temp as $$
begin
  insert into public.notifications (user_id, type, title, body, link)
  select p.id, 'organization_pending', 'Organization awaiting review',
         format('%s (%s) signed up and is awaiting verification.', new.name, new.kind), '/admin'
  from public.profiles p
  where p.role = 'admin' and p.is_demo = new.is_demo;
  return null;
end $$;

create trigger organizations_notify_admins after insert on public.organizations
  for each row execute function private.notify_admins_new_org();

create or replace function private.seed_listing(
  p_org uuid, p_creator uuid, p_title text, p_desc text, p_category text, p_diet text,
  p_qty numeric, p_unit text, p_meals integer, p_storage text,
  p_prepared timestamptz, p_safe timestamptz, p_pstart timestamptz, p_pend timestamptz,
  p_status text, p_created timestamptz, p_allergens text[], p_packaging text)
returns uuid language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_org public.organizations;
  v_id uuid;
begin
  select * into v_org from public.organizations where id = p_org;
  insert into public.food_listings (donor_org_id, created_by, title, description, category, diet, quantity,
    quantity_unit, estimated_meals, prepared_at, safe_until, pickup_start, pickup_end, storage_requirement,
    packaging, allergens, pickup_address, latitude, longitude, max_radius_km, status, handling_confirmed,
    is_demo, created_at, updated_at)
  values (p_org, p_creator, p_title, p_desc, p_category, p_diet, p_qty, p_unit, p_meals, p_prepared, p_safe,
    p_pstart, p_pend, p_storage, p_packaging, coalesce(p_allergens, '{}'), v_org.address, v_org.latitude,
    v_org.longitude, 20, p_status, true, true, p_created, p_created)
  returning id into v_id;
  return v_id;
end $$;

create or replace function private.seed_pickup(
  p_listing uuid, p_receiver_org uuid, p_requester uuid, p_volunteer uuid, p_status text,
  p_accepted_at timestamptz, p_collected_at timestamptz, p_verified_at timestamptz, p_decider uuid)
returns uuid language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_l public.food_listings;
  v_o public.organizations;
  v_req uuid;
  v_pickup uuid;
begin
  select * into v_l from public.food_listings where id = p_listing;
  select * into v_o from public.organizations where id = p_receiver_org;
  insert into public.food_requests (listing_id, receiver_org_id, requested_by, requested_quantity, message,
    status, distance_km, decided_by, decided_at, is_demo, created_at, updated_at)
  values (p_listing, p_receiver_org, p_requester, v_l.quantity, 'We can collect within the window.',
    'accepted', round(private.haversine_km(v_o.latitude, v_o.longitude, v_l.latitude, v_l.longitude)::numeric, 2),
    p_decider, p_accepted_at, true, p_accepted_at - interval '20 minutes', p_accepted_at)
  returning id into v_req;

  insert into public.pickups (listing_id, request_id, donor_org_id, receiver_org_id, volunteer_id, status,
    assigned_at, en_route_at, collected_at, collected_by, verified_at, verified_by, is_demo, created_at, updated_at)
  values (p_listing, v_req, v_l.donor_org_id, p_receiver_org, p_volunteer, p_status,
    case when p_volunteer is not null then p_accepted_at + interval '5 minutes' end,
    case when p_status in ('en_route', 'arrived', 'collected', 'verified') then p_accepted_at + interval '15 minutes' end,
    p_collected_at, case when p_collected_at is not null then coalesce(p_volunteer, p_requester) end,
    p_verified_at, case when p_verified_at is not null then p_requester end,
    true, p_accepted_at, coalesce(p_verified_at, p_collected_at, p_accepted_at))
  returning id into v_pickup;

  insert into public.audit_events (actor_id, action, entity_type, entity_id, listing_id, metadata, is_demo, created_at)
  values
    (v_l.created_by, 'listing_created', 'food_listing', v_l.id, v_l.id, jsonb_build_object('title', v_l.title), true, v_l.created_at),
    (p_requester, 'request_submitted', 'food_request', v_req, v_l.id, jsonb_build_object('receiver_org', v_o.name), true, p_accepted_at - interval '20 minutes'),
    (p_decider, 'request_accepted', 'food_request', v_req, v_l.id, jsonb_build_object('receiver_org', v_o.name), true, p_accepted_at);
  if p_collected_at is not null then
    insert into public.audit_events (actor_id, action, entity_type, entity_id, listing_id, metadata, is_demo, created_at)
    values (coalesce(p_volunteer, p_requester), 'collection_recorded', 'pickup', v_pickup, v_l.id,
            jsonb_build_object('method', 'handover_code'), true, p_collected_at);
  end if;
  if p_verified_at is not null then
    insert into public.audit_events (actor_id, action, entity_type, entity_id, listing_id, metadata, is_demo, created_at)
    values (p_requester, 'verification_completed', 'pickup', v_pickup, v_l.id,
            jsonb_build_object('meals', v_l.estimated_meals), true, p_verified_at);
  end if;
  return v_pickup;
end $$;

create or replace function public.seed_demo_data(p_donor uuid, p_receiver uuid, p_volunteer uuid, p_admin uuid)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  n timestamptz := now();
  d1 constant uuid := '00000000-0000-4000-a000-000000000d01'; -- Campus Central Canteen (demo donor login)
  d2 constant uuid := '00000000-0000-4000-a000-000000000d02'; -- Green Bowl Kitchen
  d3 constant uuid := '00000000-0000-4000-a000-000000000d03'; -- Fresh Basket Grocery
  d4 constant uuid := '00000000-0000-4000-a000-000000000d04'; -- Celebration Banquets
  r1 constant uuid := '00000000-0000-4000-a000-000000000e01'; -- Community Food Collective (demo receiver login)
  r2 constant uuid := '00000000-0000-4000-a000-000000000e02'; -- Helping Hands Food Bank
  r3 constant uuid := '00000000-0000-4000-a000-000000000e03'; -- Local Relief Network (pending)
  v_donors uuid[] := array[d1, d2, d3, d4];
  v_id uuid;
  v_req uuid;
  v_pickup uuid;
  v_x jsonb;
  v_i integer;
  v_day timestamptz;
  v_templates jsonb := '[
    ["Veg Meals Thali Surplus", "cooked_meals", "veg", 45, "portions", 45, "ambient"],
    ["Bread Loaves & Buns", "bakery", "veg", 10, "kg", 40, "ambient"],
    ["Banana & Papaya Mix", "fruits", "vegan", 18, "kg", 36, "ambient"],
    ["Seasonal Vegetables", "vegetables", "vegan", 30, "kg", 60, "ambient"],
    ["Curd Packs", "dairy", "veg", 20, "litres", 40, "refrigerated"],
    ["Egg Fried Rice", "cooked_meals", "non_veg", 35, "portions", 35, "ambient"],
    ["Biscuit & Snack Packets", "packaged_food", "veg", 90, "packets", 45, "ambient"],
    ["Buffet Veg Curries & Rice", "cooked_meals", "veg", 120, "portions", 120, "refrigerated"]
  ]';
begin
  if p_donor is null or p_receiver is null or p_volunteer is null or p_admin is null then
    raise exception 'All four demo user ids are required.';
  end if;

  -- 1. Wipe previous demo activity (audit purge is explicitly allowed for demo rows only).
  perform set_config('foodbridge.allow_audit_purge', 'on', true);
  delete from public.audit_events where is_demo;
  perform set_config('foodbridge.allow_audit_purge', 'off', true);
  delete from public.food_listings where is_demo;
  delete from public.notifications where user_id in (p_donor, p_receiver, p_volunteer, p_admin);

  -- 2. Organizations (fictional; approximate coordinates).
  insert into public.organizations (id, name, kind, org_type, address, city, latitude, longitude,
    has_refrigeration, has_freezer, capacity_meals, verification_status, is_demo)
  values
    (d1, 'Campus Central Canteen', 'donor', 'canteen', 'Central Block, VIT-AP Campus, Inavolu', 'Amaravati', 16.4963, 80.4994, true, false, 0, 'verified', true),
    (d2, 'Green Bowl Kitchen', 'donor', 'restaurant', 'Near Benz Circle, MG Road', 'Vijayawada', 16.4996, 80.6560, true, false, 0, 'verified', true),
    (d3, 'Fresh Basket Grocery', 'donor', 'grocery', 'Main Bazaar Road', 'Mangalagiri', 16.4307, 80.5525, true, true, 0, 'verified', true),
    (d4, 'Celebration Banquets', 'donor', 'banquet_hall', 'NH-16 Service Road', 'Tadepalli', 16.4800, 80.6000, true, false, 0, 'verified', true),
    (r1, 'Community Food Collective', 'receiver', 'ngo', 'Undavalli Centre Road', 'Tadepalli', 16.4850, 80.5900, true, false, 250, 'verified', true),
    (r2, 'Helping Hands Food Bank', 'receiver', 'food_bank', 'Governorpet', 'Vijayawada', 16.5131, 80.6297, true, true, 500, 'verified', true),
    (r3, 'Local Relief Network', 'receiver', 'community_org', 'Brodipet', 'Guntur', 16.3067, 80.4365, false, false, 80, 'pending', true)
  on conflict (id) do update set
    name = excluded.name, kind = excluded.kind, org_type = excluded.org_type, address = excluded.address,
    city = excluded.city, latitude = excluded.latitude, longitude = excluded.longitude,
    has_refrigeration = excluded.has_refrigeration, has_freezer = excluded.has_freezer,
    capacity_meals = excluded.capacity_meals, verification_status = excluded.verification_status,
    verification_note = null, is_demo = true;

  -- 3. Demo users.
  update public.profiles set role = 'donor', organization_id = d1, is_demo = true,
    full_name = 'Demo Donor (Canteen Manager)', phone = null where id = p_donor;
  update public.profiles set role = 'receiver', organization_id = r1, is_demo = true,
    full_name = 'Demo Receiver (NGO Coordinator)', phone = null where id = p_receiver;
  update public.profiles set role = 'volunteer', organization_id = null, is_demo = true,
    full_name = 'Demo Volunteer', phone = null where id = p_volunteer;
  update public.profiles set role = 'admin', organization_id = null, is_demo = true,
    full_name = 'Demo Administrator', phone = null where id = p_admin;

  delete from public.organization_members where user_id in (p_donor, p_receiver, p_volunteer, p_admin)
    or organization_id in (d1, d2, d3, d4, r1, r2, r3);
  insert into public.organization_members (organization_id, user_id, member_role)
  values (d1, p_donor, 'owner'), (r1, p_receiver, 'owner');

  -- 4. Open listings (relative to now).
  perform private.seed_listing(d1, p_donor, 'Veg Biryani & Raita',
    'Freshly cooked lunch surplus from the main counter. Kept covered in hot cases.',
    'cooked_meals', 'veg', 40, 'portions', 40, 'ambient', n - interval '1 hour', n + interval '3 hours',
    n - interval '10 minutes', n + interval '150 minutes', 'available', n - interval '25 minutes',
    array['dairy'], 'Steel containers (return requested)');
  perform private.seed_listing(d3, null, 'Assorted Bread & Buns',
    'Unsold bakery items from today''s batch, sealed in bags.',
    'bakery', 'veg', 12, 'kg', 60, 'ambient', n - interval '6 hours', n + interval '20 hours',
    n + interval '1 hour', n + interval '8 hours', 'available', n - interval '2 hours',
    array['gluten'], 'Sealed plastic bags');
  perform private.seed_listing(d4, null, 'Paneer Butter Masala with Rotis',
    'Banquet surplus from an evening event. Refrigerated immediately after service.',
    'cooked_meals', 'veg', 120, 'portions', 120, 'refrigerated', n - interval '2 hours', n + interval '5 hours',
    n, n + interval '4 hours', 'available', n - interval '40 minutes',
    array['dairy', 'gluten'], 'Food-grade trays with lids');
  perform private.seed_listing(d3, null, 'Fresh Vegetables Crate',
    'Tomatoes, onions, carrots and greens. Slight cosmetic blemishes only.',
    'vegetables', 'vegan', 25, 'kg', 50, 'ambient', null, n + interval '48 hours',
    n, n + interval '24 hours', 'available', n - interval '3 hours', '{}', 'Plastic crates');
  perform private.seed_listing(d3, null, 'Curd & Buttermilk Packs',
    'Sealed dairy packs, within manufacturer date, stored at 4°C.',
    'dairy', 'veg', 30, 'litres', 60, 'refrigerated', null, n + interval '10 hours',
    n, n + interval '8 hours', 'available', n - interval '90 minutes', array['dairy'], 'Sealed sachets');
  perform private.seed_listing(d2, null, 'Chicken Curry & Rice',
    'Dinner service surplus. Needs immediate pickup.',
    'cooked_meals', 'non_veg', 35, 'portions', 35, 'ambient', n - interval '90 minutes', n + interval '50 minutes',
    n - interval '30 minutes', n + interval '45 minutes', 'available', n - interval '50 minutes',
    '{}', 'Disposable containers');
  perform private.seed_listing(d3, null, 'Frozen Parathas',
    'Packaged frozen parathas, unopened cartons.',
    'packaged_food', 'veg', 80, 'packets', 80, 'frozen', null, n + interval '5 days',
    n, n + interval '48 hours', 'available', n - interval '5 hours', array['gluten'], 'Original cartons');
  perform private.seed_listing(d4, null, 'Wedding Buffet Surplus',
    'Large surplus from a wedding reception: rice, dal, mixed vegetable curry.',
    'cooked_meals', 'veg', 300, 'portions', 300, 'refrigerated', n - interval '3 hours', n + interval '6 hours',
    n, n + interval '5 hours', 'available', n - interval '30 minutes', '{}', 'Large insulated containers');

  -- 5. Listing with two pending requests (donor demo: accept / reject).
  v_id := private.seed_listing(d1, p_donor, 'Idli & Sambar Breakfast',
    'Breakfast surplus, kept in insulated containers.',
    'cooked_meals', 'veg', 50, 'portions', 50, 'ambient', n - interval '40 minutes', n + interval '4 hours',
    n, n + interval '3 hours', 'available', n - interval '35 minutes', '{}', 'Insulated containers');
  insert into public.food_requests (listing_id, receiver_org_id, requested_by, requested_quantity, message, status, distance_km, is_demo, created_at)
  values
    (v_id, r1, p_receiver, 50, 'We can send a volunteer within 30 minutes.', 'pending',
     round(private.haversine_km(16.4850, 80.5900, 16.4963, 80.4994)::numeric, 2), true, n - interval '20 minutes'),
    (v_id, r2, null, 50, 'Our van is in the area this morning.', 'pending',
     round(private.haversine_km(16.5131, 80.6297, 16.4963, 80.4994)::numeric, 2), true, n - interval '12 minutes');
  insert into public.audit_events (actor_id, action, entity_type, entity_id, listing_id, metadata, is_demo, created_at)
  values (p_donor, 'listing_created', 'food_listing', v_id, v_id, '{"title":"Idli & Sambar Breakfast"}', true, n - interval '35 minutes'),
         (p_receiver, 'request_submitted', 'food_listing', v_id, v_id, '{"receiver_org":"Community Food Collective"}', true, n - interval '20 minutes');

  -- 6. Reserved: volunteer assigned (donor generates code -> volunteer verifies -> receiver confirms).
  v_id := private.seed_listing(d1, p_donor, 'Vegetable Pulao',
    'Lunch surplus, portioned into 30 boxes.',
    'cooked_meals', 'veg', 30, 'portions', 30, 'ambient', n - interval '1 hour', n + interval '3 hours',
    n - interval '30 minutes', n + interval '2 hours', 'reserved', n - interval '70 minutes', '{}', 'Sealed boxes');
  perform private.seed_pickup(v_id, r1, p_receiver, p_volunteer, 'assigned', n - interval '45 minutes', null, null, p_donor);

  -- 7. Reserved: no volunteer yet (receiver can assign or collect directly).
  v_id := private.seed_listing(d1, p_donor, 'Fruit Salad Cups',
    'Cut fruit cups from the juice counter, chilled.',
    'fruits', 'vegan', 40, 'items', 40, 'refrigerated', n - interval '1 hour', n + interval '6 hours',
    n, n + interval '5 hours', 'reserved', n - interval '50 minutes', '{}', 'Lidded cups');
  perform private.seed_pickup(v_id, r1, p_receiver, null, 'scheduled', n - interval '30 minutes', null, null, p_donor);

  -- 8. Collected, awaiting receiver confirmation.
  v_id := private.seed_listing(d1, p_donor, 'Sandwich Trays',
    'Veg sandwiches from a cancelled department event.',
    'bakery', 'veg', 6, 'trays', 48, 'refrigerated', n - interval '3 hours', n + interval '4 hours',
    n - interval '2 hours', n + interval '3 hours', 'collected', n - interval '150 minutes', array['gluten', 'dairy'], 'Covered trays');
  perform private.seed_pickup(v_id, r1, p_receiver, p_volunteer, 'collected', n - interval '2 hours',
    n - interval '30 minutes', null, p_donor);

  -- 9. Verified rescue history over the last 30 days (drives the impact charts).
  for v_i in 1..18 loop
    v_x := v_templates -> ((v_i - 1) % 8);
    v_day := date_trunc('day', n) - make_interval(days => 29 - ((v_i * 5) % 29)) + interval '6 hours' + make_interval(mins => v_i * 13);
    v_id := private.seed_listing(v_donors[((v_i - 1) % 4) + 1],
      case when ((v_i - 1) % 4) = 0 then p_donor end,
      v_x ->> 0, 'Rescued surplus (demo history).', v_x ->> 1, v_x ->> 2, (v_x ->> 3)::numeric, v_x ->> 4,
      (v_x ->> 5)::integer, v_x ->> 6,
      v_day - interval '1 hour', v_day + interval '8 hours', v_day, v_day + interval '6 hours',
      'completed', v_day - interval '30 minutes', '{}', null);
    perform private.seed_pickup(v_id, case when v_i % 3 = 0 then r2 else r1 end,
      case when v_i % 3 = 0 then null else p_receiver end,
      case when v_i % 2 = 0 then p_volunteer end,
      'verified', v_day + interval '20 minutes', v_day + interval '2 hours', v_day + interval '3 hours', p_donor);
  end loop;

  -- 10. Expired and cancelled history.
  v_id := private.seed_listing(d2, null, 'Mixed Veg Curry', 'Not collected in time (demo).',
    'cooked_meals', 'veg', 25, 'portions', 25, 'ambient', n - interval '2 days 4 hours', n - interval '2 days',
    n - interval '2 days 3 hours', n - interval '2 days 1 hour', 'expired', n - interval '2 days 4 hours', '{}', null);
  insert into public.audit_events (actor_id, action, entity_type, entity_id, listing_id, metadata, is_demo, created_at)
  values (null, 'listing_expired', 'food_listing', v_id, v_id, '{"title":"Mixed Veg Curry"}', true, n - interval '2 days');
  v_id := private.seed_listing(d1, p_donor, 'Lemon Rice', 'Not collected in time (demo).',
    'cooked_meals', 'veg', 20, 'portions', 20, 'ambient', n - interval '5 days 4 hours', n - interval '5 days',
    n - interval '5 days 3 hours', n - interval '5 days 1 hour', 'expired', n - interval '5 days 4 hours', '{}', null);
  insert into public.audit_events (actor_id, action, entity_type, entity_id, listing_id, metadata, is_demo, created_at)
  values (null, 'listing_expired', 'food_listing', v_id, v_id, '{"title":"Lemon Rice"}', true, n - interval '5 days');
  v_id := private.seed_listing(d4, null, 'Dessert Platters', 'Cancelled by donor (demo).',
    'other', 'veg', 10, 'trays', 60, 'refrigerated', n - interval '8 days 2 hours', n - interval '8 days',
    n - interval '8 days 1 hour', n - interval '8 days 30 minutes', 'cancelled', n - interval '8 days 2 hours',
    array['dairy', 'nuts'], null);

  -- 11. Notifications for demo users.
  insert into public.notifications (user_id, type, title, body, link, created_at) values
    (p_donor, 'request_new', 'New food request', 'Community Food Collective requested "Idli & Sambar Breakfast".', '/requests', n - interval '20 minutes'),
    (p_donor, 'request_new', 'New food request', 'Helping Hands Food Bank requested "Idli & Sambar Breakfast".', '/requests', n - interval '12 minutes'),
    (p_receiver, 'request_accepted', 'Request accepted', 'Your request for "Vegetable Pulao" was accepted.', '/pickups', n - interval '45 minutes'),
    (p_receiver, 'pickup_updated', 'Food collected', '"Sandwich Trays" was collected. Confirm receipt once it arrives.', '/pickups', n - interval '30 minutes'),
    (p_volunteer, 'pickup_assigned', 'New pickup assigned', 'You have been assigned to collect "Vegetable Pulao".', '/pickups', n - interval '40 minutes'),
    (p_admin, 'organization_pending', 'Organization awaiting review', 'Local Relief Network (receiver) is awaiting verification.', '/admin', n - interval '1 day');

  return jsonb_build_object(
    'listings', (select count(*) from public.food_listings where is_demo),
    'requests', (select count(*) from public.food_requests where is_demo),
    'pickups', (select count(*) from public.pickups where is_demo));
end $$;

revoke all on function public.seed_demo_data(uuid, uuid, uuid, uuid) from public, anon, authenticated;
grant execute on function public.seed_demo_data(uuid, uuid, uuid, uuid) to service_role;

-- ===== 20261027000005_demo_seed_v2.sql =====
-- =====================================================================
-- FoodBridge — demo seed v2
--
-- Replaces the v1 demo seed function with a fuller, internally consistent
-- dataset (see docs/demo-knowledge-base.md):
--   * 4 donor + 4 receiver organizations, 4 volunteers, 1 demo admin
--   * stable, deterministic ids (md5 of a scenario key) for every listing,
--     request and pickup, so URLs and docs stay valid across re-seeds
--   * every collected / verified pickup has a used pickup_verifications row
--     (bcrypt hash of a random throwaway value — no plaintext code exists)
--     and the matching audit history
--   * decisions and confirmations are attributed only to members of the
--     organization concerned (never to an unrelated demo user)
--
-- Reset scope: only rows with is_demo = true (and notifications of demo
-- profiles) are deleted. Real data is never touched.
-- Callable only with the service-role key or from the SQL editor.
-- =====================================================================

drop function if exists public.seed_demo_data(uuid, uuid, uuid, uuid);
drop function if exists private.seed_pickup(uuid, uuid, uuid, uuid, text, timestamptz, timestamptz, timestamptz, uuid);
drop function if exists private.seed_listing(uuid, uuid, text, text, text, text, numeric, text, integer, text,
  timestamptz, timestamptz, timestamptz, timestamptz, text, timestamptz, text[], text);

-- Deterministic uuid for a demo scenario key.
create or replace function private.demo_id(p_key text)
returns uuid language sql immutable as $$
  select md5('foodbridge-demo:' || p_key)::uuid
$$;

create or replace function private.demo_listing(
  p_key text, p_org uuid, p_creator uuid, p_title text, p_desc text, p_category text, p_diet text,
  p_qty numeric, p_unit text, p_meals integer, p_storage text,
  p_prepared timestamptz, p_safe timestamptz, p_pstart timestamptz, p_pend timestamptz,
  p_status text, p_created timestamptz, p_allergens text[], p_packaging text)
returns uuid language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_org public.organizations;
  v_id uuid := private.demo_id('listing:' || p_key);
begin
  select * into v_org from public.organizations where id = p_org;
  insert into public.food_listings (id, donor_org_id, created_by, title, description, category, diet, quantity,
    quantity_unit, estimated_meals, prepared_at, safe_until, pickup_start, pickup_end, storage_requirement,
    packaging, allergens, pickup_address, latitude, longitude, max_radius_km, status, handling_confirmed,
    is_demo, created_at, updated_at)
  values (v_id, p_org, p_creator, p_title, p_desc, p_category, p_diet, p_qty, p_unit, p_meals, p_prepared, p_safe,
    p_pstart, p_pend, p_storage, p_packaging, coalesce(p_allergens, '{}'), v_org.address, v_org.latitude,
    v_org.longitude, 20, p_status, true, true, p_created, p_created);
  insert into public.audit_events (actor_id, action, entity_type, entity_id, listing_id, metadata, is_demo, created_at)
  values (p_creator, 'listing_created', 'food_listing', v_id, v_id,
          jsonb_build_object('title', p_title, 'meals', p_meals), true, p_created);
  return v_id;
end $$;

-- A request that was submitted and (optionally) decided, without a pickup.
create or replace function private.demo_request(
  p_key text, p_listing uuid, p_receiver_org uuid, p_requester uuid, p_status text, p_message text,
  p_created timestamptz, p_decider uuid, p_decided timestamptz, p_note text)
returns uuid language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_l public.food_listings;
  v_o public.organizations;
  v_id uuid := private.demo_id('request:' || p_key);
begin
  select * into v_l from public.food_listings where id = p_listing;
  select * into v_o from public.organizations where id = p_receiver_org;
  insert into public.food_requests (id, listing_id, receiver_org_id, requested_by, requested_quantity, message, status,
    distance_km, decision_note, decided_by, decided_at, is_demo, created_at, updated_at)
  values (v_id, p_listing, p_receiver_org, p_requester, v_l.quantity, p_message, p_status,
    round(private.haversine_km(v_o.latitude, v_o.longitude, v_l.latitude, v_l.longitude)::numeric, 2),
    p_note, p_decider, p_decided, true, p_created, coalesce(p_decided, p_created));
  insert into public.audit_events (actor_id, action, entity_type, entity_id, listing_id, metadata, is_demo, created_at)
  values (p_requester, 'request_submitted', 'food_request', v_id, p_listing,
          jsonb_build_object('receiver_org', v_o.name), true, p_created);
  if p_status in ('rejected', 'cancelled') then
    insert into public.audit_events (actor_id, action, entity_type, entity_id, listing_id, metadata, is_demo, created_at)
    values (case when p_status = 'cancelled' then p_requester else p_decider end,
            case when p_status = 'cancelled' then 'request_cancelled' else 'request_rejected' end,
            'food_request', v_id, p_listing,
            jsonb_build_object('receiver_org', v_o.name, 'reason', p_note), true, coalesce(p_decided, p_created));
  end if;
  return v_id;
end $$;

-- An accepted request plus its pickup, carried forward to p_status with a
-- consistent trail of timestamps, verification record and audit events.
create or replace function private.demo_pickup(
  p_key text, p_listing uuid, p_receiver_org uuid, p_requester uuid, p_decider uuid, p_volunteer uuid,
  p_status text, p_accepted timestamptz, p_collected timestamptz, p_verified timestamptz)
returns uuid language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_l public.food_listings;
  v_o public.organizations;
  v_req uuid := private.demo_id('request:' || p_key);
  v_pickup uuid := private.demo_id('pickup:' || p_key);
  v_collector uuid := coalesce(p_volunteer, p_requester);
  v_moving boolean := p_status in ('en_route', 'arrived', 'collected', 'verified');
begin
  if p_status = 'assigned' and p_volunteer is null then
    raise exception 'demo_pickup %: assigned pickups need a volunteer', p_key;
  end if;
  if p_status in ('collected', 'verified') and p_collected is null then
    raise exception 'demo_pickup %: collected pickups need a collection time', p_key;
  end if;
  if p_status = 'verified' and p_verified is null then
    raise exception 'demo_pickup %: verified pickups need a verification time', p_key;
  end if;

  select * into v_l from public.food_listings where id = p_listing;
  select * into v_o from public.organizations where id = p_receiver_org;

  insert into public.food_requests (id, listing_id, receiver_org_id, requested_by, requested_quantity, message, status,
    distance_km, decided_by, decided_at, is_demo, created_at, updated_at)
  values (v_req, p_listing, p_receiver_org, p_requester, v_l.quantity, 'We can collect within the window.', 'accepted',
    round(private.haversine_km(v_o.latitude, v_o.longitude, v_l.latitude, v_l.longitude)::numeric, 2),
    p_decider, p_accepted, true, p_accepted - interval '20 minutes', p_accepted);

  insert into public.pickups (id, listing_id, request_id, donor_org_id, receiver_org_id, volunteer_id, status,
    assigned_at, en_route_at, arrived_at, collected_at, collected_by, verified_at, verified_by, cancelled_at,
    is_demo, created_at, updated_at)
  values (v_pickup, p_listing, v_req, v_l.donor_org_id, p_receiver_org, p_volunteer, p_status,
    case when p_volunteer is not null then p_accepted + interval '5 minutes' end,
    case when v_moving then p_accepted + interval '15 minutes' end,
    case when p_status in ('arrived', 'collected', 'verified') then coalesce(p_collected - interval '10 minutes', p_accepted + interval '40 minutes') end,
    p_collected, case when p_collected is not null then v_collector end,
    p_verified, case when p_verified is not null then p_requester end,
    case when p_status in ('cancelled', 'expired') then v_l.safe_until end,
    true, p_accepted, coalesce(p_verified, p_collected, p_accepted));

  insert into public.audit_events (actor_id, action, entity_type, entity_id, listing_id, metadata, is_demo, created_at)
  values
    (p_requester, 'request_submitted', 'food_request', v_req, p_listing, jsonb_build_object('receiver_org', v_o.name), true, p_accepted - interval '20 minutes'),
    (p_decider, 'request_accepted', 'food_request', v_req, p_listing, jsonb_build_object('receiver_org', v_o.name, 'pickup_id', v_pickup), true, p_accepted);
  if p_volunteer is not null then
    insert into public.audit_events (actor_id, action, entity_type, entity_id, listing_id, metadata, is_demo, created_at)
    values (p_requester, 'pickup_assigned', 'pickup', v_pickup, p_listing, jsonb_build_object('volunteer_id', p_volunteer), true, p_accepted + interval '5 minutes');
  end if;
  if v_moving then
    insert into public.audit_events (actor_id, action, entity_type, entity_id, listing_id, metadata, is_demo, created_at)
    values (v_collector, 'pickup_status_updated', 'pickup', v_pickup, p_listing, '{"status":"en_route"}', true, p_accepted + interval '15 minutes');
  end if;

  if p_collected is not null then
    -- Used one-time code. The hashed value is random and immediately discarded:
    -- no plaintext code exists anywhere, and the row can never be used again.
    insert into public.pickup_verifications (id, pickup_id, code_hash, expires_at, attempts, used_at, used_by,
      created_by, created_at)
    values (private.demo_id('verification:' || p_key), v_pickup,
      extensions.crypt(encode(extensions.gen_random_bytes(16), 'hex'), extensions.gen_salt('bf', 6)),
      p_collected + interval '20 minutes', 0, p_collected, v_collector, v_l.created_by, p_collected - interval '10 minutes');
    insert into public.audit_events (actor_id, action, entity_type, entity_id, listing_id, metadata, is_demo, created_at)
    values
      (v_l.created_by, 'handover_code_generated', 'pickup', v_pickup, p_listing,
       jsonb_build_object('expires_at', p_collected + interval '20 minutes'), true, p_collected - interval '10 minutes'),
      (v_collector, 'collection_recorded', 'pickup', v_pickup, p_listing, '{"method":"handover_code"}', true, p_collected);
  end if;
  if p_verified is not null then
    insert into public.audit_events (actor_id, action, entity_type, entity_id, listing_id, metadata, is_demo, created_at)
    values (p_requester, 'verification_completed', 'pickup', v_pickup, p_listing,
            jsonb_build_object('meals', v_l.estimated_meals), true, p_verified);
  end if;
  return v_pickup;
end $$;

-- ---------------------------------------------------------------------
-- p_extras (optional) maps the non-login demo accounts created by
-- scripts/seed-demo.mjs:
--   { "volunteers": [uuid, ...],                -- extra volunteers
--     "org_staff":  { "<org uuid>": uuid, ... } -- one staff member per org }
-- Missing entries are tolerated: the affected history is attributed to the
-- login accounts' organizations only, never to an unrelated user.
-- ---------------------------------------------------------------------
create or replace function public.seed_demo_data(p_donor uuid, p_receiver uuid, p_volunteer uuid, p_admin uuid,
                                                 p_extras jsonb default '{}'::jsonb)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  n timestamptz := now();
  d1 constant uuid := '00000000-0000-4000-a000-000000000d01'; -- Campus Central Canteen   (login: demo donor)
  d2 constant uuid := '00000000-0000-4000-a000-000000000d02'; -- Green Bowl Kitchen
  d3 constant uuid := '00000000-0000-4000-a000-000000000d03'; -- Fresh Basket Grocery
  d4 constant uuid := '00000000-0000-4000-a000-000000000d04'; -- Celebration Banquets
  r1 constant uuid := '00000000-0000-4000-a000-000000000e01'; -- Community Food Collective (login: demo receiver)
  r2 constant uuid := '00000000-0000-4000-a000-000000000e02'; -- Helping Hands Food Bank
  r3 constant uuid := '00000000-0000-4000-a000-000000000e03'; -- Local Relief Network      (pending verification)
  r4 constant uuid := '00000000-0000-4000-a000-000000000e04'; -- Riverside Community Shelter (ambient storage only)
  v_staff jsonb := coalesce(p_extras -> 'org_staff', '{}'::jsonb);
  v_vols uuid[];
  s_d2 uuid; s_d3 uuid; s_d4 uuid; s_r2 uuid; s_r3 uuid; s_r4 uuid;
  v_all uuid[];
  v_id uuid;
  v_i integer;
  v_x jsonb;
  v_day timestamptz;
  v_donor uuid; v_donor_staff uuid; v_recv uuid; v_recv_staff uuid; v_vol uuid;
  v_templates jsonb := '[
    ["Veg Meals Thali Surplus", "cooked_meals", "veg", 45, "portions", 45, "ambient"],
    ["Bread Loaves & Buns", "bakery", "veg", 10, "kg", 40, "ambient"],
    ["Banana & Papaya Mix", "fruits", "vegan", 18, "kg", 36, "ambient"],
    ["Seasonal Vegetables", "vegetables", "vegan", 30, "kg", 60, "ambient"],
    ["Curd Packs", "dairy", "veg", 20, "litres", 40, "refrigerated"],
    ["Egg Fried Rice", "cooked_meals", "non_veg", 35, "portions", 35, "ambient"],
    ["Biscuit & Snack Packets", "packaged_food", "veg", 90, "packets", 45, "ambient"],
    ["Buffet Veg Curries & Rice", "cooked_meals", "veg", 120, "portions", 120, "refrigerated"]
  ]';
begin
  if p_donor is null or p_receiver is null or p_volunteer is null or p_admin is null then
    raise exception 'All four demo login user ids are required.';
  end if;

  s_d2 := nullif(v_staff ->> d2::text, '')::uuid;
  s_d3 := nullif(v_staff ->> d3::text, '')::uuid;
  s_d4 := nullif(v_staff ->> d4::text, '')::uuid;
  s_r2 := nullif(v_staff ->> r2::text, '')::uuid;
  s_r3 := nullif(v_staff ->> r3::text, '')::uuid;
  s_r4 := nullif(v_staff ->> r4::text, '')::uuid;
  v_vols := array[p_volunteer] || coalesce(
    (select array_agg(x::uuid) from jsonb_array_elements_text(coalesce(p_extras -> 'volunteers', '[]'::jsonb)) x), '{}');
  v_all := array_remove(array[p_donor, p_receiver, p_admin, s_d2, s_d3, s_d4, s_r2, s_r3, s_r4] || v_vols, null);

  -- 1. Reset previous demo activity only.
  perform set_config('foodbridge.allow_audit_purge', 'on', true);
  delete from public.audit_events where is_demo;
  perform set_config('foodbridge.allow_audit_purge', 'off', true);
  delete from public.food_listings where is_demo; -- cascades to requests, pickups, verifications

  -- 2. Fictional organizations (approximate coordinates, Vijayawada–VIT-AP region).
  insert into public.organizations (id, name, kind, org_type, address, city, latitude, longitude,
    has_refrigeration, has_freezer, capacity_meals, verification_status, verification_note, is_demo)
  values
    (d1, 'Campus Central Canteen', 'donor', 'canteen', 'Central Block, VIT-AP Campus, Inavolu', 'Amaravati', 16.4963, 80.4994, true, false, 0, 'verified', null, true),
    (d2, 'Green Bowl Kitchen', 'donor', 'restaurant', 'Near Benz Circle, MG Road', 'Vijayawada', 16.4996, 80.6560, true, false, 0, 'verified', null, true),
    (d3, 'Fresh Basket Grocery', 'donor', 'grocery', 'Main Bazaar Road', 'Mangalagiri', 16.4307, 80.5525, true, true, 0, 'verified', null, true),
    (d4, 'Celebration Banquets', 'donor', 'banquet_hall', 'NH-16 Service Road', 'Tadepalli', 16.4800, 80.6000, true, false, 0, 'verified', null, true),
    (r1, 'Community Food Collective', 'receiver', 'ngo', 'Undavalli Centre Road', 'Tadepalli', 16.4850, 80.5900, true, false, 250, 'verified', null, true),
    (r2, 'Helping Hands Food Bank', 'receiver', 'food_bank', 'Governorpet', 'Vijayawada', 16.5131, 80.6297, true, true, 500, 'verified', null, true),
    (r3, 'Local Relief Network', 'receiver', 'community_org', 'Brodipet', 'Guntur', 16.3067, 80.4365, false, false, 80, 'pending', null, true),
    (r4, 'Riverside Community Shelter', 'receiver', 'community_org', 'Bhavanipuram', 'Vijayawada', 16.5300, 80.5930, false, false, 60, 'verified', null, true)
  on conflict (id) do update set
    name = excluded.name, kind = excluded.kind, org_type = excluded.org_type, address = excluded.address,
    city = excluded.city, latitude = excluded.latitude, longitude = excluded.longitude,
    has_refrigeration = excluded.has_refrigeration, has_freezer = excluded.has_freezer,
    capacity_meals = excluded.capacity_meals, verification_status = excluded.verification_status,
    verification_note = excluded.verification_note, is_demo = true;

  -- 3. Demo profiles. Roles are set explicitly here; the admin role is granted to
  --    exactly one account (p_admin) and, because is_demo = true, it is limited
  --    by private.admin_can_see() to demo records.
  update public.profiles set role = 'donor', organization_id = d1, is_demo = true, phone = null,
    full_name = 'Demo Donor — Canteen Manager' where id = p_donor;
  update public.profiles set role = 'receiver', organization_id = r1, is_demo = true, phone = null,
    full_name = 'Demo Receiver — NGO Coordinator' where id = p_receiver;
  update public.profiles set role = 'admin', organization_id = null, is_demo = true, phone = null,
    full_name = 'Demo Administrator' where id = p_admin;
  update public.profiles p set role = 'volunteer', organization_id = null, is_demo = true, phone = null,
    full_name = case v.ord when 1 then 'Demo Volunteer — Kiran' when 2 then 'Demo Volunteer — Arjun'
                           when 3 then 'Demo Volunteer — Meera' else 'Demo Volunteer — Sai' end
  from unnest(v_vols) with ordinality as v(id, ord) where p.id = v.id;
  update public.profiles p set role = s.role, organization_id = s.org, is_demo = true, phone = null, full_name = s.name
  from (values (s_d2, 'donor', d2, 'Demo Staff — Green Bowl Kitchen'),
               (s_d3, 'donor', d3, 'Demo Staff — Fresh Basket Grocery'),
               (s_d4, 'donor', d4, 'Demo Staff — Celebration Banquets'),
               (s_r2, 'receiver', r2, 'Demo Staff — Helping Hands Food Bank'),
               (s_r3, 'receiver', r3, 'Demo Staff — Local Relief Network'),
               (s_r4, 'receiver', r4, 'Demo Staff — Riverside Community Shelter')) as s(uid, role, org, name)
  where p.id = s.uid;

  delete from public.organization_members
  where user_id = any(v_all) or organization_id in (d1, d2, d3, d4, r1, r2, r3, r4);
  insert into public.organization_members (organization_id, user_id, member_role)
  select org, uid, 'owner' from (values (d1, p_donor), (r1, p_receiver), (d2, s_d2), (d3, s_d3), (d4, s_d4),
                                        (r2, s_r2), (r3, s_r3), (r4, s_r4)) as m(org, uid)
  where uid is not null;

  -- Notifications are reset after the org upsert so first-run "awaiting review"
  -- notifications from the insert trigger don't linger.
  delete from public.notifications where user_id = any(v_all);

  -- 4. Open listings (scenarios 2–4).
  perform private.demo_listing('biryani', d1, p_donor, 'Veg Biryani & Raita',
    'Lunch surplus from the main counter, kept covered in hot cases since service.',
    'cooked_meals', 'veg', 40, 'portions', 40, 'ambient', n - interval '1 hour', n + interval '3 hours',
    n - interval '10 minutes', n + interval '150 minutes', 'available', n - interval '25 minutes',
    array['dairy'], 'Steel containers (return requested)');
  perform private.demo_listing('bread', d3, s_d3, 'Assorted Bread & Buns',
    'Unsold bakery items from today''s batch, sealed in bags.',
    'bakery', 'veg', 12, 'kg', 60, 'ambient', n - interval '6 hours', n + interval '20 hours',
    n + interval '1 hour', n + interval '8 hours', 'available', n - interval '2 hours',
    array['gluten'], 'Sealed plastic bags');
  perform private.demo_listing('paneer', d4, s_d4, 'Paneer Butter Masala with Rotis',
    'Evening event surplus, refrigerated immediately after service.',
    'cooked_meals', 'veg', 120, 'portions', 120, 'refrigerated', n - interval '2 hours', n + interval '5 hours',
    n, n + interval '4 hours', 'available', n - interval '40 minutes',
    array['dairy', 'gluten'], 'Food-grade trays with lids');
  perform private.demo_listing('vegetables', d3, s_d3, 'Fresh Vegetables Crate',
    'Tomatoes, onions, carrots and greens with minor cosmetic blemishes.',
    'vegetables', 'vegan', 25, 'kg', 50, 'ambient', null, n + interval '48 hours',
    n, n + interval '24 hours', 'available', n - interval '3 hours', '{}', 'Plastic crates');
  perform private.demo_listing('fruit-basket', d3, s_d3, 'Seasonal Fruit Basket',
    'Bananas, guavas and oranges, ripe — best distributed today or tomorrow.',
    'fruits', 'vegan', 15, 'kg', 30, 'ambient', null, n + interval '30 hours',
    n, n + interval '20 hours', 'available', n - interval '80 minutes', '{}', 'Cardboard boxes');
  perform private.demo_listing('curd', d3, s_d3, 'Curd & Buttermilk Packs',
    'Sealed dairy packs within the manufacturer''s date, kept in the store chiller.',
    'dairy', 'veg', 30, 'litres', 60, 'refrigerated', null, n + interval '10 hours',
    n, n + interval '8 hours', 'available', n - interval '90 minutes', array['dairy'], 'Sealed sachets');
  perform private.demo_listing('chicken-curry', d2, s_d2, 'Chicken Curry & Rice',
    'Dinner service surplus. Needs immediate pickup.',
    'cooked_meals', 'non_veg', 35, 'portions', 35, 'ambient', n - interval '90 minutes', n + interval '50 minutes',
    n - interval '30 minutes', n + interval '45 minutes', 'available', n - interval '50 minutes',
    '{}', 'Disposable containers');
  perform private.demo_listing('parathas', d3, s_d3, 'Frozen Parathas',
    'Unopened cartons of packaged frozen parathas.',
    'packaged_food', 'veg', 80, 'packets', 80, 'frozen', null, n + interval '5 days',
    n, n + interval '48 hours', 'available', n - interval '5 hours', array['gluten'], 'Original cartons');
  perform private.demo_listing('wedding-buffet', d4, s_d4, 'Wedding Buffet Surplus',
    'Rice, dal and mixed vegetable curry from a reception; chilled after service.',
    'cooked_meals', 'veg', 300, 'portions', 300, 'refrigerated', n - interval '3 hours', n + interval '6 hours',
    n, n + interval '5 hours', 'available', n - interval '30 minutes', '{}', 'Large insulated containers');

  -- 5. Requests in each non-pickup status.
  --    (Scenario 1) Idli: two pending requests -> donor accepts one.
  v_id := private.demo_listing('idli', d1, p_donor, 'Idli & Sambar Breakfast',
    'Breakfast surplus, kept in insulated containers.',
    'cooked_meals', 'veg', 50, 'portions', 50, 'ambient', n - interval '40 minutes', n + interval '4 hours',
    n, n + interval '3 hours', 'available', n - interval '35 minutes', '{}', 'Insulated containers');
  perform private.demo_request('idli-r1', v_id, r1, p_receiver, 'pending', 'We can send a volunteer within 30 minutes.',
    n - interval '20 minutes', null, null, null);
  perform private.demo_request('idli-r2', v_id, r2, s_r2, 'pending', 'Our van is in the area this morning.',
    n - interval '12 minutes', null, null, null);

  --    (Scenario 5) Fried rice: one request declined by the donor, one withdrawn by the receiver.
  v_id := private.demo_listing('fried-rice', d2, s_d2, 'Veg Fried Rice',
    'Kitchen surplus from the lunch buffet.',
    'cooked_meals', 'veg', 30, 'portions', 30, 'ambient', n - interval '1 hour', n + interval '4 hours',
    n, n + interval '3 hours', 'available', n - interval '70 minutes', array['soy'], 'Foil containers');
  perform private.demo_request('fried-rice-r4', v_id, r4, s_r4, 'rejected', 'We can pick up at 6 pm.',
    n - interval '60 minutes', s_d2, n - interval '45 minutes', 'Pickup time is after our closing; please request earlier.');
  perform private.demo_request('fried-rice-r1', v_id, r1, p_receiver, 'cancelled', 'Can collect in an hour.',
    n - interval '55 minutes', null, n - interval '40 minutes', 'Withdrawn by receiver');

  -- 6. Pickups in progress.
  --    (Scenario 6) Pulao: volunteer assigned -> code -> collected -> confirmed.
  v_id := private.demo_listing('pulao', d1, p_donor, 'Vegetable Pulao',
    'Lunch surplus, portioned into 30 sealed boxes.',
    'cooked_meals', 'veg', 30, 'portions', 30, 'ambient', n - interval '1 hour', n + interval '3 hours',
    n - interval '30 minutes', n + interval '2 hours', 'reserved', n - interval '70 minutes', '{}', 'Sealed boxes');
  perform private.demo_pickup('pulao', v_id, r1, p_receiver, p_donor, p_volunteer, 'assigned',
    n - interval '45 minutes', null, null);

  v_id := private.demo_listing('fruit-cups', d1, p_donor, 'Fruit Salad Cups',
    'Cut fruit cups from the juice counter, chilled.',
    'fruits', 'vegan', 40, 'items', 40, 'refrigerated', n - interval '1 hour', n + interval '6 hours',
    n, n + interval '5 hours', 'reserved', n - interval '50 minutes', '{}', 'Lidded cups');
  perform private.demo_pickup('fruit-cups', v_id, r1, p_receiver, p_donor, null, 'scheduled',
    n - interval '30 minutes', null, null);

  if s_r2 is not null and s_d2 is not null and array_length(v_vols, 1) >= 2 then
    v_id := private.demo_listing('tomato-rice', d2, s_d2, 'Tomato Rice Boxes',
      'Packed lunch boxes from a cancelled office order.',
      'cooked_meals', 'veg', 25, 'portions', 25, 'ambient', n - interval '90 minutes', n + interval '3 hours',
      n - interval '30 minutes', n + interval '2 hours', 'reserved', n - interval '80 minutes', '{}', 'Sealed boxes');
    perform private.demo_pickup('tomato-rice', v_id, r2, s_r2, s_d2, v_vols[2], 'en_route',
      n - interval '50 minutes', null, null);
  end if;

  --    Collected, awaiting receipt confirmation (Scenario 6, final step).
  v_id := private.demo_listing('sandwiches', d1, p_donor, 'Sandwich Trays',
    'Veg sandwiches from a cancelled department event.',
    'bakery', 'veg', 6, 'trays', 48, 'refrigerated', n - interval '3 hours', n + interval '4 hours',
    n - interval '2 hours', n + interval '3 hours', 'collected', n - interval '150 minutes', array['gluten', 'dairy'], 'Covered trays');
  perform private.demo_pickup('sandwiches', v_id, r1, p_receiver, p_donor, p_volunteer, 'collected',
    n - interval '2 hours', n - interval '30 minutes', null);

  -- 7. Verified rescue history over the last 30 days (drives impact charts).
  for v_i in 1..18 loop
    v_x := v_templates -> ((v_i - 1) % 8);
    v_day := date_trunc('day', n) - make_interval(days => 29 - ((v_i * 5) % 29)) + interval '6 hours' + make_interval(mins => v_i * 13);
    v_donor := (array[d1, d2, d3, d4])[((v_i - 1) % 4) + 1];
    v_donor_staff := case v_donor when d1 then p_donor when d2 then s_d2 when d3 then s_d3 else s_d4 end;
    if v_donor_staff is null then -- no staff account for that donor: attribute to the demo donor's org instead
      v_donor := d1; v_donor_staff := p_donor;
    end if;
    v_recv := case when v_i % 3 = 0 and s_r2 is not null then r2 else r1 end;
    v_recv_staff := case v_recv when r2 then s_r2 else p_receiver end;
    v_vol := case when v_i % 2 = 0 then v_vols[((v_i / 2 - 1) % array_length(v_vols, 1)) + 1] end;
    v_id := private.demo_listing('history-' || v_i, v_donor, v_donor_staff,
      v_x ->> 0, 'Rescued surplus (demo history).', v_x ->> 1, v_x ->> 2, (v_x ->> 3)::numeric, v_x ->> 4,
      (v_x ->> 5)::integer, v_x ->> 6,
      v_day - interval '1 hour', v_day + interval '8 hours', v_day, v_day + interval '6 hours',
      'completed', v_day - interval '30 minutes', '{}', null);
    perform private.demo_pickup('history-' || v_i, v_id, v_recv, v_recv_staff, v_donor_staff, v_vol, 'verified',
      v_day + interval '20 minutes', v_day + interval '2 hours', v_day + interval '3 hours');
  end loop;

  -- 8. Terminal non-rescue outcomes (Scenario 3: expired).
  v_id := private.demo_listing('expired-curry', d2, s_d2, 'Mixed Veg Curry', 'Not requested before its deadline (demo).',
    'cooked_meals', 'veg', 25, 'portions', 25, 'ambient', n - interval '2 days 4 hours', n - interval '2 days',
    n - interval '2 days 3 hours', n - interval '2 days 1 hour', 'expired', n - interval '2 days 4 hours', '{}', null);
  insert into public.audit_events (actor_id, action, entity_type, entity_id, listing_id, metadata, is_demo, created_at)
  values (null, 'listing_expired', 'food_listing', v_id, v_id, '{"title":"Mixed Veg Curry","previous_status":"available"}', true, n - interval '2 days');

  -- Accepted but not collected in time: listing and pickup expire, request stays accepted (as sync_expiry does).
  v_id := private.demo_listing('expired-khichdi', d1, p_donor, 'Dal Khichdi', 'Accepted but not collected before the deadline (demo).',
    'cooked_meals', 'veg', 20, 'portions', 20, 'ambient', n - interval '5 days 4 hours', n - interval '5 days',
    n - interval '5 days 3 hours', n - interval '5 days 1 hour', 'expired', n - interval '5 days 4 hours', '{}', null);
  perform private.demo_pickup('expired-khichdi', v_id, r1, p_receiver, p_donor, null, 'expired',
    n - interval '5 days 2 hours', null, null);
  insert into public.audit_events (actor_id, action, entity_type, entity_id, listing_id, metadata, is_demo, created_at)
  values (null, 'listing_expired', 'food_listing', v_id, v_id, '{"title":"Dal Khichdi","previous_status":"reserved"}', true, n - interval '5 days');

  v_id := private.demo_listing('cancelled-desserts', d4, s_d4, 'Dessert Platters', 'Cancelled by the donor (demo).',
    'other', 'veg', 10, 'trays', 60, 'refrigerated', n - interval '8 days 2 hours', n - interval '8 days',
    n - interval '8 days 1 hour', n - interval '8 days 30 minutes', 'cancelled', n - interval '8 days 2 hours',
    array['dairy', 'nuts'], null);
  perform private.demo_request('cancelled-desserts-r2', v_id, r2, s_r2, 'cancelled', 'We have freezer space.',
    n - interval '8 days 100 minutes', null, n - interval '8 days 90 minutes', 'Listing cancelled by donor');
  insert into public.audit_events (actor_id, action, entity_type, entity_id, listing_id, metadata, is_demo, created_at)
  values (s_d4, 'listing_cancelled', 'food_listing', v_id, v_id, '{"reason":"Event extended; food served on site"}', true, n - interval '8 days 90 minutes');

  v_id := private.demo_listing('removed-sweets', d2, s_d2, 'Assorted Sweets Box', 'Removed by moderator (demo).',
    'other', 'veg', 5, 'kg', 25, 'ambient', n - interval '3 days 3 hours', n - interval '3 days',
    n - interval '3 days 2 hours', n - interval '3 days 1 hour', 'removed', n - interval '3 days 3 hours', '{}', null);
  update public.food_listings set moderation_note = 'Allergen information missing for nut-based sweets. Please relist with allergens declared.'
  where id = v_id;
  insert into public.audit_events (actor_id, action, entity_type, entity_id, listing_id, metadata, is_demo, created_at)
  values (p_admin, 'listing_removed', 'food_listing', v_id, v_id, '{"note":"Allergen information missing"}', true, n - interval '3 days 150 minutes');

  -- 9. Notifications consistent with the records above.
  insert into public.notifications (user_id, type, title, body, link, created_at)
  select uid, type, title, body, link, at from (values
    (p_donor, 'request_new', 'New food request', 'Community Food Collective requested "Idli & Sambar Breakfast".', '/requests', n - interval '20 minutes'),
    (p_donor, 'request_new', 'New food request', 'Helping Hands Food Bank requested "Idli & Sambar Breakfast".', '/requests', n - interval '12 minutes'),
    (p_donor, 'pickup_updated', 'Handover verified', '"Sandwich Trays" was collected. The handover code was verified.', '/pickups', n - interval '30 minutes'),
    (p_receiver, 'request_accepted', 'Request accepted', 'Your request for "Vegetable Pulao" was accepted.', '/pickups', n - interval '45 minutes'),
    (p_receiver, 'request_accepted', 'Request accepted', 'Your request for "Fruit Salad Cups" was accepted.', '/pickups', n - interval '30 minutes'),
    (p_receiver, 'pickup_updated', 'Food collected', '"Sandwich Trays" was collected. Confirm receipt once it arrives.', '/pickups', n - interval '30 minutes'),
    (p_volunteer, 'pickup_assigned', 'New pickup assigned', 'You have been assigned to collect "Vegetable Pulao".', '/pickups', n - interval '40 minutes'),
    (p_admin, 'organization_pending', 'Organization awaiting review', 'Local Relief Network (receiver) is awaiting verification.', '/admin', n - interval '1 day'),
    (s_r4, 'request_rejected', 'Request declined', 'Your request for "Veg Fried Rice" was declined.', '/requests', n - interval '45 minutes'),
    (s_d2, 'listing_removed', 'Listing removed by moderator', '"Assorted Sweets Box" was removed. Note: Allergen information missing.', '/listings/' || private.demo_id('listing:removed-sweets'), n - interval '3 days 150 minutes')
  ) as t(uid, type, title, body, link, at)
  where uid is not null;

  return jsonb_build_object(
    'organizations', (select count(*) from public.organizations where is_demo),
    'listings', (select count(*) from public.food_listings where is_demo),
    'requests', (select count(*) from public.food_requests where is_demo),
    'pickups', (select count(*) from public.pickups where is_demo),
    'verifications', (select count(*) from public.pickup_verifications v join public.pickups p on p.id = v.pickup_id where p.is_demo),
    'volunteers', array_length(v_vols, 1));
end $$;

revoke all on function public.seed_demo_data(uuid, uuid, uuid, uuid, jsonb) from public, anon, authenticated;
grant execute on function public.seed_demo_data(uuid, uuid, uuid, uuid, jsonb) to service_role;
revoke all on function private.demo_id(text), private.demo_listing(text, uuid, uuid, text, text, text, text, numeric, text,
  integer, text, timestamptz, timestamptz, timestamptz, timestamptz, text, timestamptz, text[], text),
  private.demo_request(text, uuid, uuid, uuid, text, text, timestamptz, uuid, timestamptz, text),
  private.demo_pickup(text, uuid, uuid, uuid, uuid, uuid, text, timestamptz, timestamptz, timestamptz) from public;

-- ===== 20261027000006_security_hardening.sql =====
-- =====================================================================
-- FoodBridge — security hardening (audit 2026-10-27)
--
-- 1. Anonymous visitors get column-limited reads: no admin review notes,
--    creator account ids or internal moderation fields.
-- 2. Signed-in users can no longer execute the generic private.log_audit()
--    (it would allow forged audit events if the private schema were ever
--    exposed). The listing audit trigger now calls a narrow function that
--    derives everything from the row and only logs for the donor's own org.
-- =====================================================================

-- 1. Column-limited anonymous access ------------------------------------
revoke select on public.organizations from anon;
grant select (id, name, kind, org_type, city, verification_status, is_demo) on public.organizations to anon;

revoke select on public.food_listings from anon;
grant select (id, donor_org_id, title, description, category, diet, quantity, quantity_unit, estimated_meals,
  prepared_at, safe_until, pickup_start, pickup_end, storage_requirement, packaging, allergens, pickup_address,
  latitude, longitude, max_radius_km, status, handling_confirmed, is_demo, created_at, updated_at)
  on public.food_listings to anon;

-- 2. Narrow audit logging for direct listing writes ----------------------
create or replace function private.audit_listing_write(p_listing_id uuid, p_op text)
returns void language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_l public.food_listings;
begin
  select * into v_l from public.food_listings where id = p_listing_id;
  if v_l.id is null or p_op not in ('INSERT', 'UPDATE') or not private.is_org_member(v_l.donor_org_id) then
    return; -- nothing to log for rows the caller does not own
  end if;
  insert into public.audit_events (actor_id, action, entity_type, entity_id, listing_id, metadata, is_demo)
  values (auth.uid(), case p_op when 'INSERT' then 'listing_created' else 'listing_updated' end,
          'food_listing', v_l.id, v_l.id,
          case p_op when 'INSERT' then jsonb_build_object('title', v_l.title, 'meals', v_l.estimated_meals)
                    else jsonb_build_object('title', v_l.title) end,
          v_l.is_demo);
end $$;

create or replace function private.audit_listing_change()
returns trigger language plpgsql set search_path = public, pg_temp as $$
begin
  if current_user not in ('authenticated', 'anon') then
    return null; -- RPCs (running as the owner) write their own audit events
  end if;
  perform private.audit_listing_write(new.id, tg_op);
  return null;
end $$;

revoke all on function private.audit_listing_write(uuid, text) from public;
grant execute on function private.audit_listing_write(uuid, text) to authenticated;
revoke execute on function private.log_audit(text, text, uuid, uuid, jsonb, boolean) from authenticated;

-- ===== 20261031000001_demo_org_rename.sql =====
-- =====================================================================
-- Rename the demo donor organization (d1) to "Central Canteen".
-- Redefines seed_demo_data() so `npm run seed:demo` keeps the new name,
-- and renames the existing row so no reseed is needed. Only the name
-- string changes; ids, roles and is_demo are untouched.
-- =====================================================================

update public.organizations set name = 'Central Canteen'
where id = '00000000-0000-4000-a000-000000000d01' and is_demo;

-- ---------------------------------------------------------------------
-- p_extras (optional) maps the non-login demo accounts created by
-- scripts/seed-demo.mjs:
--   { "volunteers": [uuid, ...],                -- extra volunteers
--     "org_staff":  { "<org uuid>": uuid, ... } -- one staff member per org }
-- Missing entries are tolerated: the affected history is attributed to the
-- login accounts' organizations only, never to an unrelated user.
-- ---------------------------------------------------------------------
create or replace function public.seed_demo_data(p_donor uuid, p_receiver uuid, p_volunteer uuid, p_admin uuid,
                                                 p_extras jsonb default '{}'::jsonb)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  n timestamptz := now();
  d1 constant uuid := '00000000-0000-4000-a000-000000000d01'; -- Central Canteen          (login: demo donor)
  d2 constant uuid := '00000000-0000-4000-a000-000000000d02'; -- Green Bowl Kitchen
  d3 constant uuid := '00000000-0000-4000-a000-000000000d03'; -- Fresh Basket Grocery
  d4 constant uuid := '00000000-0000-4000-a000-000000000d04'; -- Celebration Banquets
  r1 constant uuid := '00000000-0000-4000-a000-000000000e01'; -- Community Food Collective (login: demo receiver)
  r2 constant uuid := '00000000-0000-4000-a000-000000000e02'; -- Helping Hands Food Bank
  r3 constant uuid := '00000000-0000-4000-a000-000000000e03'; -- Local Relief Network      (pending verification)
  r4 constant uuid := '00000000-0000-4000-a000-000000000e04'; -- Riverside Community Shelter (ambient storage only)
  v_staff jsonb := coalesce(p_extras -> 'org_staff', '{}'::jsonb);
  v_vols uuid[];
  s_d2 uuid; s_d3 uuid; s_d4 uuid; s_r2 uuid; s_r3 uuid; s_r4 uuid;
  v_all uuid[];
  v_id uuid;
  v_i integer;
  v_x jsonb;
  v_day timestamptz;
  v_donor uuid; v_donor_staff uuid; v_recv uuid; v_recv_staff uuid; v_vol uuid;
  v_templates jsonb := '[
    ["Veg Meals Thali Surplus", "cooked_meals", "veg", 45, "portions", 45, "ambient"],
    ["Bread Loaves & Buns", "bakery", "veg", 10, "kg", 40, "ambient"],
    ["Banana & Papaya Mix", "fruits", "vegan", 18, "kg", 36, "ambient"],
    ["Seasonal Vegetables", "vegetables", "vegan", 30, "kg", 60, "ambient"],
    ["Curd Packs", "dairy", "veg", 20, "litres", 40, "refrigerated"],
    ["Egg Fried Rice", "cooked_meals", "non_veg", 35, "portions", 35, "ambient"],
    ["Biscuit & Snack Packets", "packaged_food", "veg", 90, "packets", 45, "ambient"],
    ["Buffet Veg Curries & Rice", "cooked_meals", "veg", 120, "portions", 120, "refrigerated"]
  ]';
begin
  if p_donor is null or p_receiver is null or p_volunteer is null or p_admin is null then
    raise exception 'All four demo login user ids are required.';
  end if;

  s_d2 := nullif(v_staff ->> d2::text, '')::uuid;
  s_d3 := nullif(v_staff ->> d3::text, '')::uuid;
  s_d4 := nullif(v_staff ->> d4::text, '')::uuid;
  s_r2 := nullif(v_staff ->> r2::text, '')::uuid;
  s_r3 := nullif(v_staff ->> r3::text, '')::uuid;
  s_r4 := nullif(v_staff ->> r4::text, '')::uuid;
  v_vols := array[p_volunteer] || coalesce(
    (select array_agg(x::uuid) from jsonb_array_elements_text(coalesce(p_extras -> 'volunteers', '[]'::jsonb)) x), '{}');
  v_all := array_remove(array[p_donor, p_receiver, p_admin, s_d2, s_d3, s_d4, s_r2, s_r3, s_r4] || v_vols, null);

  -- 1. Reset previous demo activity only.
  perform set_config('foodbridge.allow_audit_purge', 'on', true);
  delete from public.audit_events where is_demo;
  perform set_config('foodbridge.allow_audit_purge', 'off', true);
  delete from public.food_listings where is_demo; -- cascades to requests, pickups, verifications

  -- 2. Fictional organizations (approximate coordinates, Vijayawada–VIT-AP region).
  insert into public.organizations (id, name, kind, org_type, address, city, latitude, longitude,
    has_refrigeration, has_freezer, capacity_meals, verification_status, verification_note, is_demo)
  values
    (d1, 'Central Canteen', 'donor', 'canteen', 'Central Block, VIT-AP Campus, Inavolu', 'Amaravati', 16.4963, 80.4994, true, false, 0, 'verified', null, true),
    (d2, 'Green Bowl Kitchen', 'donor', 'restaurant', 'Near Benz Circle, MG Road', 'Vijayawada', 16.4996, 80.6560, true, false, 0, 'verified', null, true),
    (d3, 'Fresh Basket Grocery', 'donor', 'grocery', 'Main Bazaar Road', 'Mangalagiri', 16.4307, 80.5525, true, true, 0, 'verified', null, true),
    (d4, 'Celebration Banquets', 'donor', 'banquet_hall', 'NH-16 Service Road', 'Tadepalli', 16.4800, 80.6000, true, false, 0, 'verified', null, true),
    (r1, 'Community Food Collective', 'receiver', 'ngo', 'Undavalli Centre Road', 'Tadepalli', 16.4850, 80.5900, true, false, 250, 'verified', null, true),
    (r2, 'Helping Hands Food Bank', 'receiver', 'food_bank', 'Governorpet', 'Vijayawada', 16.5131, 80.6297, true, true, 500, 'verified', null, true),
    (r3, 'Local Relief Network', 'receiver', 'community_org', 'Brodipet', 'Guntur', 16.3067, 80.4365, false, false, 80, 'pending', null, true),
    (r4, 'Riverside Community Shelter', 'receiver', 'community_org', 'Bhavanipuram', 'Vijayawada', 16.5300, 80.5930, false, false, 60, 'verified', null, true)
  on conflict (id) do update set
    name = excluded.name, kind = excluded.kind, org_type = excluded.org_type, address = excluded.address,
    city = excluded.city, latitude = excluded.latitude, longitude = excluded.longitude,
    has_refrigeration = excluded.has_refrigeration, has_freezer = excluded.has_freezer,
    capacity_meals = excluded.capacity_meals, verification_status = excluded.verification_status,
    verification_note = excluded.verification_note, is_demo = true;

  -- 3. Demo profiles. Roles are set explicitly here; the admin role is granted to
  --    exactly one account (p_admin) and, because is_demo = true, it is limited
  --    by private.admin_can_see() to demo records.
  update public.profiles set role = 'donor', organization_id = d1, is_demo = true, phone = null,
    full_name = 'Demo Donor — Canteen Manager' where id = p_donor;
  update public.profiles set role = 'receiver', organization_id = r1, is_demo = true, phone = null,
    full_name = 'Demo Receiver — NGO Coordinator' where id = p_receiver;
  update public.profiles set role = 'admin', organization_id = null, is_demo = true, phone = null,
    full_name = 'Demo Administrator' where id = p_admin;
  update public.profiles p set role = 'volunteer', organization_id = null, is_demo = true, phone = null,
    full_name = case v.ord when 1 then 'Demo Volunteer — Kiran' when 2 then 'Demo Volunteer — Arjun'
                           when 3 then 'Demo Volunteer — Meera' else 'Demo Volunteer — Sai' end
  from unnest(v_vols) with ordinality as v(id, ord) where p.id = v.id;
  update public.profiles p set role = s.role, organization_id = s.org, is_demo = true, phone = null, full_name = s.name
  from (values (s_d2, 'donor', d2, 'Demo Staff — Green Bowl Kitchen'),
               (s_d3, 'donor', d3, 'Demo Staff — Fresh Basket Grocery'),
               (s_d4, 'donor', d4, 'Demo Staff — Celebration Banquets'),
               (s_r2, 'receiver', r2, 'Demo Staff — Helping Hands Food Bank'),
               (s_r3, 'receiver', r3, 'Demo Staff — Local Relief Network'),
               (s_r4, 'receiver', r4, 'Demo Staff — Riverside Community Shelter')) as s(uid, role, org, name)
  where p.id = s.uid;

  delete from public.organization_members
  where user_id = any(v_all) or organization_id in (d1, d2, d3, d4, r1, r2, r3, r4);
  insert into public.organization_members (organization_id, user_id, member_role)
  select org, uid, 'owner' from (values (d1, p_donor), (r1, p_receiver), (d2, s_d2), (d3, s_d3), (d4, s_d4),
                                        (r2, s_r2), (r3, s_r3), (r4, s_r4)) as m(org, uid)
  where uid is not null;

  -- Notifications are reset after the org upsert so first-run "awaiting review"
  -- notifications from the insert trigger don't linger.
  delete from public.notifications where user_id = any(v_all);

  -- 4. Open listings (scenarios 2–4).
  perform private.demo_listing('biryani', d1, p_donor, 'Veg Biryani & Raita',
    'Lunch surplus from the main counter, kept covered in hot cases since service.',
    'cooked_meals', 'veg', 40, 'portions', 40, 'ambient', n - interval '1 hour', n + interval '3 hours',
    n - interval '10 minutes', n + interval '150 minutes', 'available', n - interval '25 minutes',
    array['dairy'], 'Steel containers (return requested)');
  perform private.demo_listing('bread', d3, s_d3, 'Assorted Bread & Buns',
    'Unsold bakery items from today''s batch, sealed in bags.',
    'bakery', 'veg', 12, 'kg', 60, 'ambient', n - interval '6 hours', n + interval '20 hours',
    n + interval '1 hour', n + interval '8 hours', 'available', n - interval '2 hours',
    array['gluten'], 'Sealed plastic bags');
  perform private.demo_listing('paneer', d4, s_d4, 'Paneer Butter Masala with Rotis',
    'Evening event surplus, refrigerated immediately after service.',
    'cooked_meals', 'veg', 120, 'portions', 120, 'refrigerated', n - interval '2 hours', n + interval '5 hours',
    n, n + interval '4 hours', 'available', n - interval '40 minutes',
    array['dairy', 'gluten'], 'Food-grade trays with lids');
  perform private.demo_listing('vegetables', d3, s_d3, 'Fresh Vegetables Crate',
    'Tomatoes, onions, carrots and greens with minor cosmetic blemishes.',
    'vegetables', 'vegan', 25, 'kg', 50, 'ambient', null, n + interval '48 hours',
    n, n + interval '24 hours', 'available', n - interval '3 hours', '{}', 'Plastic crates');
  perform private.demo_listing('fruit-basket', d3, s_d3, 'Seasonal Fruit Basket',
    'Bananas, guavas and oranges, ripe — best distributed today or tomorrow.',
    'fruits', 'vegan', 15, 'kg', 30, 'ambient', null, n + interval '30 hours',
    n, n + interval '20 hours', 'available', n - interval '80 minutes', '{}', 'Cardboard boxes');
  perform private.demo_listing('curd', d3, s_d3, 'Curd & Buttermilk Packs',
    'Sealed dairy packs within the manufacturer''s date, kept in the store chiller.',
    'dairy', 'veg', 30, 'litres', 60, 'refrigerated', null, n + interval '10 hours',
    n, n + interval '8 hours', 'available', n - interval '90 minutes', array['dairy'], 'Sealed sachets');
  perform private.demo_listing('chicken-curry', d2, s_d2, 'Chicken Curry & Rice',
    'Dinner service surplus. Needs immediate pickup.',
    'cooked_meals', 'non_veg', 35, 'portions', 35, 'ambient', n - interval '90 minutes', n + interval '50 minutes',
    n - interval '30 minutes', n + interval '45 minutes', 'available', n - interval '50 minutes',
    '{}', 'Disposable containers');
  perform private.demo_listing('parathas', d3, s_d3, 'Frozen Parathas',
    'Unopened cartons of packaged frozen parathas.',
    'packaged_food', 'veg', 80, 'packets', 80, 'frozen', null, n + interval '5 days',
    n, n + interval '48 hours', 'available', n - interval '5 hours', array['gluten'], 'Original cartons');
  perform private.demo_listing('wedding-buffet', d4, s_d4, 'Wedding Buffet Surplus',
    'Rice, dal and mixed vegetable curry from a reception; chilled after service.',
    'cooked_meals', 'veg', 300, 'portions', 300, 'refrigerated', n - interval '3 hours', n + interval '6 hours',
    n, n + interval '5 hours', 'available', n - interval '30 minutes', '{}', 'Large insulated containers');

  -- 5. Requests in each non-pickup status.
  --    (Scenario 1) Idli: two pending requests -> donor accepts one.
  v_id := private.demo_listing('idli', d1, p_donor, 'Idli & Sambar Breakfast',
    'Breakfast surplus, kept in insulated containers.',
    'cooked_meals', 'veg', 50, 'portions', 50, 'ambient', n - interval '40 minutes', n + interval '4 hours',
    n, n + interval '3 hours', 'available', n - interval '35 minutes', '{}', 'Insulated containers');
  perform private.demo_request('idli-r1', v_id, r1, p_receiver, 'pending', 'We can send a volunteer within 30 minutes.',
    n - interval '20 minutes', null, null, null);
  perform private.demo_request('idli-r2', v_id, r2, s_r2, 'pending', 'Our van is in the area this morning.',
    n - interval '12 minutes', null, null, null);

  --    (Scenario 5) Fried rice: one request declined by the donor, one withdrawn by the receiver.
  v_id := private.demo_listing('fried-rice', d2, s_d2, 'Veg Fried Rice',
    'Kitchen surplus from the lunch buffet.',
    'cooked_meals', 'veg', 30, 'portions', 30, 'ambient', n - interval '1 hour', n + interval '4 hours',
    n, n + interval '3 hours', 'available', n - interval '70 minutes', array['soy'], 'Foil containers');
  perform private.demo_request('fried-rice-r4', v_id, r4, s_r4, 'rejected', 'We can pick up at 6 pm.',
    n - interval '60 minutes', s_d2, n - interval '45 minutes', 'Pickup time is after our closing; please request earlier.');
  perform private.demo_request('fried-rice-r1', v_id, r1, p_receiver, 'cancelled', 'Can collect in an hour.',
    n - interval '55 minutes', null, n - interval '40 minutes', 'Withdrawn by receiver');

  -- 6. Pickups in progress.
  --    (Scenario 6) Pulao: volunteer assigned -> code -> collected -> confirmed.
  v_id := private.demo_listing('pulao', d1, p_donor, 'Vegetable Pulao',
    'Lunch surplus, portioned into 30 sealed boxes.',
    'cooked_meals', 'veg', 30, 'portions', 30, 'ambient', n - interval '1 hour', n + interval '3 hours',
    n - interval '30 minutes', n + interval '2 hours', 'reserved', n - interval '70 minutes', '{}', 'Sealed boxes');
  perform private.demo_pickup('pulao', v_id, r1, p_receiver, p_donor, p_volunteer, 'assigned',
    n - interval '45 minutes', null, null);

  v_id := private.demo_listing('fruit-cups', d1, p_donor, 'Fruit Salad Cups',
    'Cut fruit cups from the juice counter, chilled.',
    'fruits', 'vegan', 40, 'items', 40, 'refrigerated', n - interval '1 hour', n + interval '6 hours',
    n, n + interval '5 hours', 'reserved', n - interval '50 minutes', '{}', 'Lidded cups');
  perform private.demo_pickup('fruit-cups', v_id, r1, p_receiver, p_donor, null, 'scheduled',
    n - interval '30 minutes', null, null);

  if s_r2 is not null and s_d2 is not null and array_length(v_vols, 1) >= 2 then
    v_id := private.demo_listing('tomato-rice', d2, s_d2, 'Tomato Rice Boxes',
      'Packed lunch boxes from a cancelled office order.',
      'cooked_meals', 'veg', 25, 'portions', 25, 'ambient', n - interval '90 minutes', n + interval '3 hours',
      n - interval '30 minutes', n + interval '2 hours', 'reserved', n - interval '80 minutes', '{}', 'Sealed boxes');
    perform private.demo_pickup('tomato-rice', v_id, r2, s_r2, s_d2, v_vols[2], 'en_route',
      n - interval '50 minutes', null, null);
  end if;

  --    Collected, awaiting receipt confirmation (Scenario 6, final step).
  v_id := private.demo_listing('sandwiches', d1, p_donor, 'Sandwich Trays',
    'Veg sandwiches from a cancelled department event.',
    'bakery', 'veg', 6, 'trays', 48, 'refrigerated', n - interval '3 hours', n + interval '4 hours',
    n - interval '2 hours', n + interval '3 hours', 'collected', n - interval '150 minutes', array['gluten', 'dairy'], 'Covered trays');
  perform private.demo_pickup('sandwiches', v_id, r1, p_receiver, p_donor, p_volunteer, 'collected',
    n - interval '2 hours', n - interval '30 minutes', null);

  -- 7. Verified rescue history over the last 30 days (drives impact charts).
  for v_i in 1..18 loop
    v_x := v_templates -> ((v_i - 1) % 8);
    v_day := date_trunc('day', n) - make_interval(days => 29 - ((v_i * 5) % 29)) + interval '6 hours' + make_interval(mins => v_i * 13);
    v_donor := (array[d1, d2, d3, d4])[((v_i - 1) % 4) + 1];
    v_donor_staff := case v_donor when d1 then p_donor when d2 then s_d2 when d3 then s_d3 else s_d4 end;
    if v_donor_staff is null then -- no staff account for that donor: attribute to the demo donor's org instead
      v_donor := d1; v_donor_staff := p_donor;
    end if;
    v_recv := case when v_i % 3 = 0 and s_r2 is not null then r2 else r1 end;
    v_recv_staff := case v_recv when r2 then s_r2 else p_receiver end;
    v_vol := case when v_i % 2 = 0 then v_vols[((v_i / 2 - 1) % array_length(v_vols, 1)) + 1] end;
    v_id := private.demo_listing('history-' || v_i, v_donor, v_donor_staff,
      v_x ->> 0, 'Rescued surplus (demo history).', v_x ->> 1, v_x ->> 2, (v_x ->> 3)::numeric, v_x ->> 4,
      (v_x ->> 5)::integer, v_x ->> 6,
      v_day - interval '1 hour', v_day + interval '8 hours', v_day, v_day + interval '6 hours',
      'completed', v_day - interval '30 minutes', '{}', null);
    perform private.demo_pickup('history-' || v_i, v_id, v_recv, v_recv_staff, v_donor_staff, v_vol, 'verified',
      v_day + interval '20 minutes', v_day + interval '2 hours', v_day + interval '3 hours');
  end loop;

  -- 8. Terminal non-rescue outcomes (Scenario 3: expired).
  v_id := private.demo_listing('expired-curry', d2, s_d2, 'Mixed Veg Curry', 'Not requested before its deadline (demo).',
    'cooked_meals', 'veg', 25, 'portions', 25, 'ambient', n - interval '2 days 4 hours', n - interval '2 days',
    n - interval '2 days 3 hours', n - interval '2 days 1 hour', 'expired', n - interval '2 days 4 hours', '{}', null);
  insert into public.audit_events (actor_id, action, entity_type, entity_id, listing_id, metadata, is_demo, created_at)
  values (null, 'listing_expired', 'food_listing', v_id, v_id, '{"title":"Mixed Veg Curry","previous_status":"available"}', true, n - interval '2 days');

  -- Accepted but not collected in time: listing and pickup expire, request stays accepted (as sync_expiry does).
  v_id := private.demo_listing('expired-khichdi', d1, p_donor, 'Dal Khichdi', 'Accepted but not collected before the deadline (demo).',
    'cooked_meals', 'veg', 20, 'portions', 20, 'ambient', n - interval '5 days 4 hours', n - interval '5 days',
    n - interval '5 days 3 hours', n - interval '5 days 1 hour', 'expired', n - interval '5 days 4 hours', '{}', null);
  perform private.demo_pickup('expired-khichdi', v_id, r1, p_receiver, p_donor, null, 'expired',
    n - interval '5 days 2 hours', null, null);
  insert into public.audit_events (actor_id, action, entity_type, entity_id, listing_id, metadata, is_demo, created_at)
  values (null, 'listing_expired', 'food_listing', v_id, v_id, '{"title":"Dal Khichdi","previous_status":"reserved"}', true, n - interval '5 days');

  v_id := private.demo_listing('cancelled-desserts', d4, s_d4, 'Dessert Platters', 'Cancelled by the donor (demo).',
    'other', 'veg', 10, 'trays', 60, 'refrigerated', n - interval '8 days 2 hours', n - interval '8 days',
    n - interval '8 days 1 hour', n - interval '8 days 30 minutes', 'cancelled', n - interval '8 days 2 hours',
    array['dairy', 'nuts'], null);
  perform private.demo_request('cancelled-desserts-r2', v_id, r2, s_r2, 'cancelled', 'We have freezer space.',
    n - interval '8 days 100 minutes', null, n - interval '8 days 90 minutes', 'Listing cancelled by donor');
  insert into public.audit_events (actor_id, action, entity_type, entity_id, listing_id, metadata, is_demo, created_at)
  values (s_d4, 'listing_cancelled', 'food_listing', v_id, v_id, '{"reason":"Event extended; food served on site"}', true, n - interval '8 days 90 minutes');

  v_id := private.demo_listing('removed-sweets', d2, s_d2, 'Assorted Sweets Box', 'Removed by moderator (demo).',
    'other', 'veg', 5, 'kg', 25, 'ambient', n - interval '3 days 3 hours', n - interval '3 days',
    n - interval '3 days 2 hours', n - interval '3 days 1 hour', 'removed', n - interval '3 days 3 hours', '{}', null);
  update public.food_listings set moderation_note = 'Allergen information missing for nut-based sweets. Please relist with allergens declared.'
  where id = v_id;
  insert into public.audit_events (actor_id, action, entity_type, entity_id, listing_id, metadata, is_demo, created_at)
  values (p_admin, 'listing_removed', 'food_listing', v_id, v_id, '{"note":"Allergen information missing"}', true, n - interval '3 days 150 minutes');

  -- 9. Notifications consistent with the records above.
  insert into public.notifications (user_id, type, title, body, link, created_at)
  select uid, type, title, body, link, at from (values
    (p_donor, 'request_new', 'New food request', 'Community Food Collective requested "Idli & Sambar Breakfast".', '/requests', n - interval '20 minutes'),
    (p_donor, 'request_new', 'New food request', 'Helping Hands Food Bank requested "Idli & Sambar Breakfast".', '/requests', n - interval '12 minutes'),
    (p_donor, 'pickup_updated', 'Handover verified', '"Sandwich Trays" was collected. The handover code was verified.', '/pickups', n - interval '30 minutes'),
    (p_receiver, 'request_accepted', 'Request accepted', 'Your request for "Vegetable Pulao" was accepted.', '/pickups', n - interval '45 minutes'),
    (p_receiver, 'request_accepted', 'Request accepted', 'Your request for "Fruit Salad Cups" was accepted.', '/pickups', n - interval '30 minutes'),
    (p_receiver, 'pickup_updated', 'Food collected', '"Sandwich Trays" was collected. Confirm receipt once it arrives.', '/pickups', n - interval '30 minutes'),
    (p_volunteer, 'pickup_assigned', 'New pickup assigned', 'You have been assigned to collect "Vegetable Pulao".', '/pickups', n - interval '40 minutes'),
    (p_admin, 'organization_pending', 'Organization awaiting review', 'Local Relief Network (receiver) is awaiting verification.', '/admin', n - interval '1 day'),
    (s_r4, 'request_rejected', 'Request declined', 'Your request for "Veg Fried Rice" was declined.', '/requests', n - interval '45 minutes'),
    (s_d2, 'listing_removed', 'Listing removed by moderator', '"Assorted Sweets Box" was removed. Note: Allergen information missing.', '/listings/' || private.demo_id('listing:removed-sweets'), n - interval '3 days 150 minutes')
  ) as t(uid, type, title, body, link, at)
  where uid is not null;

  return jsonb_build_object(
    'organizations', (select count(*) from public.organizations where is_demo),
    'listings', (select count(*) from public.food_listings where is_demo),
    'requests', (select count(*) from public.food_requests where is_demo),
    'pickups', (select count(*) from public.pickups where is_demo),
    'verifications', (select count(*) from public.pickup_verifications v join public.pickups p on p.id = v.pickup_id where p.is_demo),
    'volunteers', array_length(v_vols, 1));
end $$;

revoke all on function public.seed_demo_data(uuid, uuid, uuid, uuid, jsonb) from public, anon, authenticated;
grant execute on function public.seed_demo_data(uuid, uuid, uuid, uuid, jsonb) to service_role;
